-- English Retail walkthroughs. Sources are recorded per achievement below.
-- All retained General IDs have numbered walkthroughs and difficulty ratings.
-- Parent comments and relevant replies reviewed; reviewedAt records curation.
local _, TDP = ...
TDP.CollectionWalkthroughs = TDP.CollectionWalkthroughs or {}
TDP.CollectionWalkthroughs.achievements = TDP.CollectionWalkthroughs.achievements or {}
local guides = TDP.CollectionWalkthroughs.achievements

local function pin(mapID, x, y, step, label, mapName)
    return { mapID = mapID, x = x / 100, y = y / 100, step = step, label = label, mapName = mapName }
end

local function add(id, name, steps, waypoints, tips, comments, category)
    local lines, sources = {}, {}
    local originals = TDP.PatchCatalog.achievementDetails.general
    local original = originals and originals[id] or {}
    for index, text in ipairs(steps) do lines[index] = index .. ". " .. text end
    for _, comment in ipairs(comments or {}) do
        sources[#sources + 1] = type(comment) == "number"
            and ("https://www.wowhead.com/achievement=" .. id .. "#comments:id=" .. comment) or comment
    end
    if #sources == 0 then sources[1] = "https://www.wowhead.com/achievement=" .. id .. "#comments" end
    guides[id] = {
        achievementId = id, name = name, category = category or "Other", sourceType = "Achievement", source = name,
        acquisition = table.concat(lines, "\n\n"), stepCount = #steps,
        waypoints = waypoints or {}, tips = tips, sources = sources,
        wowheadUrl = "https://www.wowhead.com/achievement=" .. id,
        sourceURL = "https://www.wowhead.com/achievement=" .. id .. "#comments",
        reviewedAt = "2026-11-04",
        description = original.description, requirements = original.requirements,
        cost = original.cost, costs = original.costs, notes = original.notes,
    }
end

add(153, "The Old Gnome and the Sea", {
    "Learn Fishing and travel to a visible school of fish. The Forgotten Pools in Northern Barrens are an accessible example; Steam Pump Flotsam in Zangarmarsh is another qualifying pool type.",
    "Stand close enough to cast into the circle of disturbed water. Recast when the bobber lands outside the circle; casting beside a school and catching the same fish from open water is not the intended method.",
    "Click the bobber when a fish bites and loot the catch. One qualifying school is enough; you do not need to fish every school type. If a newer expansion's pool does not award credit, try a school in an original zone.",
}, {pin(10,37.5,45.6,1,"The Forgotten Pools - search the water for fish schools"),pin(102,65,60,1,"The Lagoon - alternative Steam Pump Flotsam search area")}, "Find Fish tracking is a separate unlock: see Fish Don't Leave Footprints. Pool pins mark search areas, not guaranteed active spawns.", {1353289,1570410,6065536}, "Professions")

add(1243, "Fish Don't Leave Footprints", {
    "Learn Fishing, then visit Olirea beside the fishing trainer in the Silvermoon Bazaar, in the MIDNIGHT version of Silvermoon City (45.0, 59.7). Buy Angler's Guide (item 228954). Fishing-supplies vendors in Khaz Algar also sell this book.",
    "Use the purchased guide to learn Find Fish. Open the minimap tracking menu and enable Fish or Find Fish. The unlock applies outside its vendor's expansion too; you do not need to reach an old 100-point Fishing requirement first.",
    "If you cannot reach a vendor, use the original alternative: fish Steam Pump Flotsam or other wreckage pools, open the trunks/crates you catch, and learn the Weather-Beaten Journal when it drops. Keep fishing schools rather than ordinary open water when pursuing these containers.",
}, {pin(2393,44.98,59.69,1,"Olirea - Angler's Guide, Midnight Silvermoon Bazaar"),pin(102,65,60,3,"The Lagoon - alternative flotsam and crate search area")}, "The purchased book teaches fish-school tracking outside its vendor's expansion too. If this character already knows Find Fish, no second book is needed. The old journal remains an alternative.", {5928587,6129610,"https://www.wowhead.com/item=228954/anglers-guide","https://www.wowhead.com/achievement=1243#comments:id=6129610:reply=1830455"}, "Professions")

add(1257, "The Scavenger", {
    "Learn Fishing and enable Find Fish if available. Track the five wreckage criteria. At every stop, cast INSIDE the named pool and LOOT a catch; ordinary open water beside it does not satisfy the criterion. One credited catch per wreckage TYPE is sufficient. You can leave the remaining catches for another player.",
    "In Zangarmarsh, circle The Lagoon and Umbrafen Lake for Steam Pump Flotsam. First check whether a flotsam pool is already up. If none is present, fish nearby Brackish Mixed Schools until they disappear, then circle back to check the new spawns. Apply this same clear-and-recheck method at the later stops rather than waiting at one empty point.",
    "In Northern Stranglethorn, follow the coast south of Grom'gol for Bloodsail Wreckage. Alternatively, follow the Cape of Stranglethorn's EAST coast by Ruins of Aboraz around 63.2, 47.0. These are alternatives for one criterion. Use the current split Stranglethorn maps, not the single-map coordinates from 2008 comments.",
    "In Wetlands, check the Menethil Harbor docks, bridge and surrounding flooded shoreline for Schooner Wreckage. Expand the circuit beyond the docks if none is present.",
    "For Waterlogged Wreckage, search the inland waters around Shok'Thokar in southeastern Desolace, including 73.8, 71.3. A January 2026 reply confirms this area. Check nearby small ponds too; this wreckage is not restricted to the sea. Alternatively, follow Feralas's coast south from Camp Ataya toward the shore north of Feathermoon Stronghold, around 38, 35. Stop once either area credits Waterlogged.",
    "For Floating Wreckage, follow Tanaris's eastern coast south from the old Steamwheedle area to Wavestrider Beach, north of Caverns of Time, around 65.6, 40.3. Clear nearby schools and repeat the circuit if needed. Feralas's Waterlogged Wreckage is a different criterion. Check that all five types are credited before leaving the final zone.",
}, {pin(102,65,60,2,"The Lagoon - flotsam circuit"),pin(102,72,77,2,"Umbrafen Lake - flotsam circuit"),pin(50,37,58,3,"South of Grom'gol - coastal wreckage circuit"),pin(210,63.2,47,3,"Ruins of Aboraz - alternative EAST-coast Bloodsail circuit"),pin(56,10.8,59.4,4,"Menethil docks - Schooner Wreckage search"),pin(56,16,50,4,"Menethil bridge and flooded coast"),pin(66,73.8,71.3,5,"Shok'Thokar inland waters - Waterlogged Wreckage search"),pin(69,38,35,5,"Coast north of Feathermoon - alternative Waterlogged search"),pin(71,67,23,6,"Old Steamwheedle coast - start the Floating Wreckage circuit"),pin(71,65.6,40.3,6,"Wavestrider Beach - continue the Floating Wreckage search")}, "Pins mark search areas, not guaranteed active pools. A wreckage may already be present: a preliminary lap can save unnecessary fishing. If Stranglethorn pools disappear as you approach while Bwemba's Spirit follows you, finish that quest chain and relog to leave its special phase. The old 5.1 Bloodsail bug was fixed; the July 2025 complaint was also edited to report a fix.", {3297591,413857,1354526,5351507,5470220,5756695,6050803,6146349,"https://www.wowhead.com/comment/show-replies?id=413857","https://www.wowhead.com/comment/show-replies?id=1354526","https://www.wowhead.com/comment/show-replies?id=3297591","https://www.wowhead.com/comment/show-replies?id=5470220","https://www.wowhead.com/comment/show-replies?id=1582940",1309989,1444015}, "Professions")

add(878, "One That Didn't Get Away", {
    "Track the achievement: you need ONE of its qualifying rare fish, not every fish on the list. Learn Fishing and clear bag space before starting. You must personally fish up AND LOOT the catch; seeing it in the loot window or buying someone else's fish is insufficient.",
    "Visit Chromie at the TOP of Wyrmrest Temple in Dragonblight. Complete The Day That Chromie Dies, then Rewind, to unlock repeatable attempts at The Deaths of Chromie. This is the Legion scenario, not Chromie Time levelling. If Andorhal is not yet available, do the Emerald Dragonshrine unlock below.",
    "Inside the scenario, complete the Emerald Dragonshrine attack around 63.5, 73.2: collect 24 Emeraldine Plumes and 30 Twisted Fibers, make three Nightmare-Catchers and use them to defeat the six Dream Tormentors. Defeat Thalas Vylethorn by the skull/hand statue, loot his Gleaming Chronoshard and turn it in to unlock the Andorhal portal.",
    "Start another attempt, speak to Chromie to begin, then take the Andorhal portal on your left. Leave the burning building and reach the river. Fish OPEN WATER for a 32 Pound Catfish; no school is needed. A September 2026 reply identifies water beside the bridge around 39.25, 71.25 on the SCENARIO's Andorhal map.",
    "Keep fishing until the scenario timer expires, then restart and return through the unlocked portal. It stays unlocked between attempts. The smaller catfish do not stack, so empty bags between runs and keep Auto Loot enabled. Loot the 32 Pound Catfish when it appears and check credit immediately. Reports range from a few casts to many full attempts; there is no guaranteed number of runs.",
    "For an outdoor route without scenario unlocks, fish open water at Stonebull Lake in Mulgore, around 44.3, 61.1, for a 15 Pound Mud Snapper. Alliance characters should keep clear of Bloodhoof Village's Horde guards. Stay at a safe part of the lake rather than entering the village.",
    "Alternatively, fish open water at Crystal Lake in Elwynn Forest, beside the memorial island around 48.47, 65.61, for the same 15 Pound Mud Snapper. A March 2026 comment and its August reply confirm this route. These outdoor stops are alternatives to Andorhal; stop as soon as one qualifying catch awards the achievement.",
}, {pin(115,59.9,54.7,2,"Wyrmrest Temple - Chromie is on top"),pin(897,63.5,73.2,3,"Emerald Dragonshrine - unlock Andorhal","The Deaths of Chromie - Dragonblight"),pin(899,39.25,71.25,4,"Scenario Andorhal - fish by the bridge","The Deaths of Chromie - Andorhal"),pin(7,44.3,61.1,6,"Stonebull Lake - alternative 15 Pound Mud Snapper"),pin(37,48.47,65.61,7,"Crystal Lake memorial island - alternative 15 Pound Mud Snapper")}, "Andorhal inside The Deaths of Chromie still has a November 3, 2026 catch confirmation using an ordinary Midnight fishing pole. An Underlight Angler is not required. Enter through the scenario portal; ordinary Western Plaguelands is a different location. Higher skill can reduce junk but does not guarantee the rare fish. The 10/12 Pound Mud Snapper and 17/19/22/26 Pound Catfish do not satisfy these routes.", {2510734,439105,5783177,6364775,6413110,6464983,6307415,1166446,"https://www.wowhead.com/comment/show-replies?id=2510734","https://www.wowhead.com/comment/show-replies?id=5783177","https://www.wowhead.com/comment/show-replies?id=6307415","https://www.wowhead.com/comment/show-replies?id=1166446","https://wago.tools/db2/UiMap/csv"}, "Professions")

for _, fish in ipairs({{1556,25},{1557,50},{1558,100},{1559,250},{1560,500},{1561,1000}}) do
    add(fish[1], fish[2] .. " Fish", {
        "Learn Fishing, put the Fishing ability on an action bar and stand by reachable water. The canals beside Stormwind's fishing trainer are one option; choose a safe pool nearer you if preferred.",
        "Cast, wait for the bobber to splash, then click it and LOOT the catch. Casting repeatedly without looting does not build this counter. Fish do not need to come from a school or be a rare species.",
        "Continue until the achievement records " .. fish[2] .. " items fished. Work on schools, wreckage or a rare-fish achievement at the same time to avoid a separate grind; the name is a milestone rather than a requirement for " .. fish[2] .. " different species.",
        "For an alternative with several counted items per cast, travel to LEGION Dalaran over the Broken Isles and take the eastern sewer entrance near 59.4, 47.5. This is not Northrend Dalaran. Speak to Raethan inside if you want to hire his temporary bodyguard before entering the sewer's PvP area.",
        "Search the northeastern sewer room, the old Black Market area around 70.5, 20, for green Shimmering Whorl pools. Fish inside those pools and loot the Sightless Eyes. Comments report that each eye adds to this achievement, often several from one cast; check your first catch, then continue between active pools. Ordinary sewer water is not the same loot table.",
    }, {pin(84,55,69,1,"Stormwind canals - optional safe fishing water"),pin(627,59.4,47.5,4,"Eastern sewer entrance - Legion Dalaran","Dalaran (Broken Isles)"),pin(628,68.6,58.4,4,"Raethan - temporary bodyguard","Dalaran Underbelly (Broken Isles)"),pin(628,70.5,20,5,"Old Black Market room - Shimmering Whorl search area","Dalaran Underbelly (Broken Isles)")}, "Loot everything caught, including junk. Older comments that exclude wreckage and non-fish items predate the counting fix. The sewer pin marks the room to search, not a guaranteed pool spawn. The bodyguard is temporary; renew it with Raethan if needed. No old level-450 Fishing requirement applies.", {"https://www.wowhead.com/achievement=1556#comments:id=410192","https://www.wowhead.com/achievement=1561#comments:id=639206","https://www.wowhead.com/achievement=1561#comments:id=2580402","https://www.wowhead.com/achievement=1561#comments:id=5527212","https://www.wowhead.com/object=250642/shimmering-whorl","https://www.wowhead.com/npc=97359/raethan"}, "Professions")
end

add(1832, "Tastes Like Chicken", {
    "Track the counter and leave room in your bags. You need to EAT 50 different qualifying items, not purchase 50 copies of one food. Buy one of each missing item you can currently consume; low-level characters cannot use every vendor food yet.",
    "ALLIANCE: begin at Innkeeper Allison in Stormwind's Trade District (60.5, 75.1) for meat/bread, then Ben Trias's cheese shop (66.4, 73.5). Choose the older food progression, such as Tough Jerky through Roasted Quail, Tough Hunk of Bread through Homemade Cherry Pie, and Darnassian Bleu through Alterac Swiss. Skip this city's route on a Horde character.",
    "HORDE: buy distinct meat from Olvia around 50.8, 72.2 and fruit from Shan'ti around 50.8, 74.2 in Orgrimmar. Continue to Miwana in the Valley of Wisdom (39.0, 48.6) for cheese and bread, then Kor'jus in/near the Cleft of Shadow for mushrooms. His older progression includes Forest Mushroom Cap, Red-Speckled Mushroom, Spongy Morel, Delicious Cave Mold, Raw Black Truffle, Dried King Bolete and Zangar Caps. Skip duplicate bread/meat already eaten from the inn.",
    "EITHER FACTION: use Shattrath's Lower City to fill missing food families. Brendan Turner sells meat, Muffin Man Moser sells bread, Oloraak sells fish, and Granny Smith sells fruit. Buy and eat their missing OLD foods. Granny's current stock includes Shiny Red Apple, Goldenbark Apple, Deep Fried Plantains, Skethyl Berries and Telaari Grapes; do not assume she sells every fruit mentioned in old lists.",
    "Eat each item and watch for the counter to rise before moving on. Starting the eating action is sufficient; you need not wait the full 30 seconds. If an older food says a stronger effect is active, cancel your current food effect and try again. A vendor selling the same item as another vendor does not create another entry.",
    "For remaining entries, learn Fishing and eat each different EDIBLE fish you catch. Raw Brilliant Smallfish, Raw Longjaw Mud Snapper and Raw Bristle Whisker Catfish are examples. Their cooked dishes are separate items, so cook and eat those too if still missing. Non-edible crafting fish and eating the same species repeatedly do not fill different entries.",
    "If still short, cook or buy inexpensive finished Classic dishes such as Spice Bread, Herb Baked Egg, Roasted Boar Meat, Charred Wolf Meat, Spiced Wolf Meat, Boiled Clams, Coyote Steak, Crab Cake, Dry Pork Ribs or Cooked Crab Claw. EAT each missing dish and stop at 50. Buying a recipe or learning it is not eating its food. Water belongs to It's Happy Hour Somewhere.",
}, {pin(84,60.5,75.1,2,"Innkeeper Allison - Alliance meat and bread"),pin(84,66.4,73.5,2,"Ben Trias - Alliance cheese"),pin(85,50.8,72.2,3,"Olvia - Horde meat"),pin(85,50.8,74.2,3,"Shan'ti - Horde fruit"),pin(85,39,48.6,3,"Miwana - Horde cheese and bread"),pin(85,49.8,61.4,3,"Kor'jus - mushroom vendor near the Cleft of Shadow"),pin(111,60.5,69.5,4,"Brendan Turner - neutral meat vendor"),pin(111,61.6,69.6,4,"Muffin Man Moser - neutral bread vendor"),pin(111,58.6,15.6,4,"Oloraak - neutral fish vendor"),pin(111,63.6,68.4,4,"Granny Smith - neutral fruit vendor")}, "Raw and cooked edible fish can provide separate entries, and each older food family fills different gaps. Legion and later foods do not all count for this older achievement; check a purchase before buying more of the same family. No additional tracking addon is required.", {998997,388957,407877,437539,596443,1336451,3122420,"https://www.wowhead.com/comment/show-replies?id=388957","https://www.wowhead.com/comment/show-replies?id=413003","https://www.wowhead.com/npc=23263/brendan-turner","https://www.wowhead.com/npc=19664/muffin-man-moser","https://www.wowhead.com/npc=19045/oloraak","https://www.wowhead.com/npc=19223/granny-smith","https://www.wowhead.com/npc=3312/olvia","https://www.wowhead.com/npc=3342/shanti","https://www.wowhead.com/npc=44785/miwana","https://www.wowhead.com/npc=3329/korjus"}, "Exploration")

add(1833, "It's Happy Hour Somewhere", {
    "Track the achievement and buy ONE of each missing older drink from Innkeeper Allison in Stormwind (Alliance) or Innkeeper Gryshka in Orgrimmar (Horde). Water, milk and juice count; this does not require 25 alcoholic drinks. Use only items your current level permits you to consume.",
    "Work through Refreshing Spring Water, Ice Cold Milk, Melon Juice, Sweet Nectar, Moonberry Juice, Morning Glory Dew, Filtered Draenic Water, Fresh Water, Pungent Seal Whey, Honeymint Tea, Sparkling Oasis Water and Highland Spring Water. Drink each once and check the counter. Start with the inexpensive missing drinks rather than buying stacks.",
    "Travel to Milly Brewtap, the neutral barmaid at Fuselight in Badlands (64.4, 38.4). Buy the five familiar spirits under their CURRENT names: Bottle of Dalaran Noir, Flask of Stormwind Tawny, Skin of Dwarven Stout, Flagon of Dwarven Mead and Jug of Badlands Bourbon. These replace names such as Pinot Noir and Flask of Port in the older comment.",
    "From Milly, also buy Glass of Eversong Wine, Bottle of Silvermoon Port, Flask of Bitter Cactus Cider, Cup of Frog Venom Brew and Skin of Mulgore Firewater, if missing. Sample each; the same drink bought from two vendors is still one entry.",
    "Finish her older selection with Fizzy Fruit Wine, Imported E.K. Ale, Potent Pineapple Punch, Banana Cocktail and Tol Barad Coconut Rum. Together the two vendor stops offer more than 25 distinct candidates, so stop when the counter awards the achievement rather than consuming every expensive newer item.",
    "If some were already sampled or a purchase gives no credit, use a different missing OLD beverage, such as Captain Rumsey's Lager. Check your counter before buying more; later comments report many Legion/BfA drinks do not count. There is no need to wait for Brewfest or recover removed quest rewards.",
}, {pin(84,60.5,75.1,1,"Innkeeper Allison - Alliance water, milk and juice"),pin(85,53.6,78.8,1,"Innkeeper Gryshka - Horde water, milk and juice"),pin(15,64.4,38.4,3,"Milly Brewtap - five renamed older spirits"),pin(15,64.4,38.4,4,"Milly Brewtap - Eversong and racial drinks"),pin(15,64.4,38.4,5,"Milly Brewtap - five fruit and imported drinks")}, "Buy one of each missing drink and consume it before buying more. A mage can no longer conjure nine separate water ranks. Milly is neutral and available to both factions; the former Goblin Slums bartender can be hidden by Embassy phasing.", {377585,3242767,5202926,"https://www.wowhead.com/comment/show-replies?id=422551","https://www.wowhead.com/comment/show-replies?id=376228","https://www.wowhead.com/npc=48064/milly-brewtap"}, "Exploration")

-- These are queue-interface milestones with no fixed world destination.
-- Do not attach an unrelated Northrend entrance just to enable a map button.
for _, finder in ipairs({{4476,"Looking For More",10},{4477,"Looking For Many",50},{4478,"Looking For Multitudes",100}}) do
    add(finder[1],finder[2],{
        "Open Group Finder > Dungeon Finder and choose an available RANDOM HEROIC queue. Selecting a specific Heroic dungeon or walking through a dungeon portal does not satisfy this queue requirement.",
        "Queue alone for the most random teammates per completion, or bring a friend if that makes queuing easier. You and players already in your party when you queue do not count as random teammates. Queue afresh after a completed run; continuing with the same assembled party can stop it adding new random teammates.",
        "Finish the dungeon, including its final boss. Repeat random Heroics until the achievement counter reaches " .. finder[3] .. " random players. A full run with four qualifying teammates can add four, so this counts PLAYERS rather than requiring " .. finder[3] .. " separate dungeons.",
        "If Random Heroic is absent, inspect a Heroic in the Specific Dungeons list to see its current level and equipment requirements, meet those requirements, then return to the RANDOM queue. Changing your portrait's dungeon difficulty does not turn a Random Normal queue into Random Heroic.",
        finder[1] == 4478 and "At 100 random players, check your mail for the Perky Pug reward and learn it. Looking For Many, the earlier 50-player milestone, awards the Patient title." or (finder[1] == 4477 and "At 50 random players, check the Patient title in your character's title list. Continue the same activity toward Looking For Multitudes and its Perky Pug reward." or "At 10 random players, check Looking For More. Continue toward Looking For Many at 50 and Looking For Multitudes at 100."),
    },{},"Use the counter on the achievement itself to confirm progress. Do not assume that Random Normal, Follower or Timewalking runs qualify; later comments report inconsistent Timewalking credit. This achievement has no fixed map location.",{"https://www.wowhead.com/achievement=4476#comments:id=910570","https://www.wowhead.com/achievement=4477#comments:id=1112369","https://www.wowhead.com/achievement=4478#comments:id=5451389","https://www.wowhead.com/achievement=4478#comments:id=6462728","https://www.wowhead.com/comment/show-replies?id=5451389"},"Dungeons")
end

-- No fixed destination exists for levels, riding skills or queue milestones.
-- Location-based routes below use explicit step numbers instead of arbitrary pins.
for _, milestone in ipairs({{6,10},{7,20},{8,30},{9,40}}) do
    add(milestone[1], "Level " .. milestone[2], {
        "Play a permanent Retail character and complete its introductory quest line. Turn in quests for experience; killing enemies without turning in their quests is usually slower.",
        "Continue questing, or use the level-appropriate Dungeon Finder once it becomes available, until this character reaches level " .. milestone[2] .. ". The requirement is this character's level, rather than levels added together across alts.",
        "Check the Level " .. milestone[2] .. " achievement after levelling. If experience has been disabled on this character, re-enable it before continuing. No special trainer, item purchase or visit to Northrend is required.",
    }, {}, "Older comments describe pre-squish levels and class unlocks. This guide uses the current Level " .. milestone[2] .. " record; the historical Level 50-80 records have been removed from this catalogue.", {}, "Other")
end

for _, riding in ipairs({{889,"Fast and Furious",10,"Journeyman"},{890,"Into the Wild Blue Yonder",20,"Expert"}}) do
    add(riding[1], riding[2], {
        "Level a permanent Retail character to " .. riding[3] .. ". Retail automatically teaches " .. riding[4] .. " Riding at this threshold; the old trainer purchase and gold cost are obsolete.",
        "Open the Mount Journal and summon a learned mount. For Expert Riding, use an area where flight is allowed; restricted zones and introductory scenarios can prevent flight without removing the riding skill.",
        "Check the achievement after reaching the required level. Buying another mount or visiting an old riding trainer is unnecessary when the skill is already learned.",
    }, {}, "The War Within changed the older comment's thresholds: Journeyman is now learned at 10 and Expert at 20. Apprentice and Artisan Riding were removed, so their retired achievements are excluded. A new neutral Pandaren must finish choosing a faction before riding unlocks.", {"https://www.wowhead.com/achievement=889#comments:id=5650305","https://www.wowhead.com/achievement=890#comments:id=6023502","https://worldofwarcraft.blizzard.com/en-us/news/24119590","https://www.wowhead.com/spell=34090/expert-riding"}, "Other")
end

add(31, "A Simple Re-Quest", {
    "Choose a repeatable DAILY quest available to your character, such as the cooking or fishing daily in Northrend Dalaran. Accept it, do its objectives and hand it in; merely accepting it does not count.",
    "Complete at least one daily after each daily reset for five consecutive days. Track this achievement and inspect the counter after each hand-in. The quest can differ between days; completing five on the same day is not the stated requirement.",
    "If the counter stalls, a September 2026 numbered comment supplies a specific workaround: bring five or six permanent characters to Anchorite Ayuri at Sun's Reach, 48.4, 36.6 on the BURNING CRUSADE Isle of Quel'Danas. Use the past Quel'Thalas phase if needed, rather than looking for her on Midnight's island map.",
    "On each character to whom Ayuri offers Your Continued Support, accept the daily and pay its 10-gold donation. Log into the next character immediately and repeat while checking the achievement. The commenter needed up to six characters because the first hand-in might not count. Characters already Exalted with the Shattered Sun Offensive may not see this quest; use the ordinary five-day route if the workaround is unavailable or fails to advance your counter.",
}, {pin(125,40.3,66.1,1,"Katherine Lee - Alliance cooking daily"),pin(125,70.0,38.9,1,"Awilo Lon'gomba - Horde cooking daily"),pin(122,48.4,36.6,3,"Anchorite Ayuri - donation workaround","Isle of Quel'Danas (Burning Crusade)"),pin(122,48.4,36.6,4,"Your Continued Support - 10 gold on each eligible character","Isle of Quel'Danas (Burning Crusade)")}, "The 2008 restrictions on battlegrounds, continents and repeating exactly the same quest describe old bugs. Midnight reports still conflict, so the donation route is a reported workaround rather than a guaranteed fix. It is the permanent Your Continued Support daily, not its removed predecessor A Charitable Donation.", {429542,700649,6256599,6310896,6412506,"https://www.wowhead.com/quest=11548/your-continued-support","https://www.wowhead.com/npc=25112/anchorite-ayuri"}, "Questing")

for _, quest in ipairs({{503,50},{504,100},{505,250},{506,500},{507,1000},{508,1500},{32,2000},{978,3000}}) do
    add(quest[1], quest[2] .. " Quests Completed", {
        "Track this achievement to see how many quest completions it currently recognises. Choose an unfinished zone story instead of repeatedly accepting and abandoning the same quest.",
        "Enable low-level quest tracking on the minimap if you outlevel the area. Complete the ordinary quests at one hub, turn them in and follow their follow-ups to the next hub; introductory and short delivery quests also provide completions.",
        "For an accessible old-world start, Alliance can take Marshal Dughan's quests in Goldshire, Elwynn Forest (42.2, 65.8); Horde can take Gar'Thok's quests in Razor Hill, Durotar (51.8, 43.4). Use a hub your character has not already completed, pick up its nearby side quests and finish the follow-ups before travelling elsewhere.",
        "Continue through unfinished zone stories until the counter reaches " .. quest[2] .. ". The quest-map chapters for Loremaster help identify unfinished stories, but this count milestone does not itself award Loremaster. Dungeon quests and class/profession introductions can fill gaps; old cloth donations and removed attunements are unnecessary.",
        "Check progress after several hand-ins when trying a repeatable activity. Many repeatables and modern world activities do not behave like unique story quests, so switch to an unfinished quest line if that activity does not move the counter.",
    }, {pin(37,42.2,65.8,3,"Marshal Dughan - optional Alliance quest hub"),pin(1,51.8,43.4,3,"Gar'Thok - optional Horde quest hub")}, "Use the achievement counter rather than the Statistics page's total, which can include dailies counted separately. If an old character's counter looks stale after a loading screen, complete a new quest and check again. Old fixed quest totals per continent and before-Cataclysm completion deadlines are obsolete.", {"https://www.wowhead.com/achievement=32#comments:id=475198","https://www.wowhead.com/achievement=978#comments:id=417643","https://www.wowhead.com/achievement=978#comments:id=634460","https://www.wowhead.com/achievement=978#comments:id=1192584","https://www.wowhead.com/achievement=978#comments:id=2620342","https://www.wowhead.com/npc=240/marshal-dughan","https://www.wowhead.com/npc=3139/garthok"}, "Questing")
end

for _, daily in ipairs({{973,5},{974,50},{975,200},{976,500},{977,1000}}) do
    add(daily[1], daily[2] .. " Daily Quests Completed", {
        "Track the achievement, then accept an available daily quest in a hub you have unlocked. A concrete starting option is your faction's Northrend Dalaran cooking daily; learn the required Cooking tier before taking it.",
        "Complete its objectives and return to the quest giver to claim the reward. Recheck the achievement counter after the hand-in. Weekly quests, world quests and repeatable turn-ins are not automatically daily quests.",
        "Do other available dailies that day, then return after the next daily reset. Continue until the counter reaches " .. daily[2] .. "; this cumulative milestone does not require consecutive days.",
    }, {pin(125,40.3,66.1,1,"Katherine Lee - Alliance daily"),pin(125,70.0,38.9,1,"Awilo Lon'gomba - Horde daily")}, "Combine this with Cooking Award progress if those daily rewards are still needed. Do not rely on removed daily dungeon or battleground quests mentioned in early comments.", {}, "Questing")
end

add(227, "Damage Control", {
    "Open Group Finder > Player vs. Player and join a battleground against players. Track Damage Control before entering so you can check progress during the match.",
    "Deal 300,000 damage to enemy PLAYERS, or do 300,000 effective healing to players, within that one battle. Choose either damage or healing; splitting 150,000 into each is not the stated requirement.",
    "Stay with the fighting group and continue helping at objectives until one counter passes 300,000. Damage to battleground creatures, target dummies or buildings is not player damage, and totals from separate matches do not combine.",
}, {}, "The old level-70 gearing and health numbers in comments are obsolete. Use the current match scoreboard and achievement tracker; no particular battleground entrance or world location is required.", {407584}, "PvP")

add(229, "The Grim Reaper", {
    "Join a player battleground and stay near your team's main fight. Large fights give more opportunities for shared honorable-kill credit than isolated duels.",
    "Help defeat enemy players and receive 30 honorable kills in that single match. These are HONORABLE KILLS, not 30 personal killing blows; healers can contribute without switching to a damage specialization.",
    "Watch the match scoreboard, return to the fighting after deaths and stay until you have the required credit. Kills from separate battlegrounds do not satisfy the one-battle description.",
}, {}, "Unexpected credit reported from unrelated activities is not a dependable route. Use actual battleground participation.", {408269,1602845}, "PvP")

add(231, "Wrecking Ball", {
    "Track Wrecking Ball and prepare a damage specialization, suitable PvP equipment and your defensive abilities. A healer friend helps. Use the KILLING BLOWS column on the scoreboard: honorable kills and damage totals are different counters.",
    "One current option is Group Finder > Player vs. Player > Training Grounds. January-February 2026 comments and replies report credit in Silvershard Mines and Battle for Gilneas. This is the newer Training Grounds queue; the old Comp Stomp brawl has repeated reports of no credit.",
    "In that battle, or in an ordinary player battleground, earn 20 personal killing blows before your first death. Stay close to your group, help bring targets low, then use a ready direct-damage or execute ability to land the final hit. Do not chase a nearly dead enemy into a group that can kill you.",
    "When focused or outnumbered, use a defensive ability early and retreat toward friendly players. Recover health before returning to the fight. Avoid lethal falls and enemy NPCs too: an NPC death can spoil the attempt even when the scoreboard is misleading.",
    "If you die or the match ends before 20 killing blows, attempt a fresh match. If 20 killing blows and zero deaths give no credit, record the match and check how many kills were actual opposing combatants; pets and other NPCs can make some battleground scoreboards misleading. Support granting credit is not guaranteed.",
}, {}, "Training Grounds credit is supported by several 12.0 reports, including a reply confirming Battle for Gilneas; check the tracker during your attempt in case later updates change it. Knockbacks into lethal terrain are not a reliable source of killing-blow credit. Removed Strand of the Ancients routes and old twink gear lists are excluded.", {338105,802772,428655,1423735,3244570,6258292,6266995,"https://www.wowhead.com/comment/show-replies?id=6266995","https://www.wowhead.com/comment/show-replies?id=6258292","https://worldofwarcraft.blizzard.com/en-us/news/24264417"}, "PvP")

for _, hk in ipairs({{238,1},{513,100},{515,500},{516,1000},{512,5000},{509,10000},{239,25000},{869,50000},{870,100000}}) do
    add(hk[1], hk[1] == 238 and "An Honorable Kill" or hk[2] .. " Honorable Kills", {
        "Queue for player battlegrounds or epic battlegrounds and track this achievement. World PvP can also count when the opponent is an eligible honorable kill.",
        "Stay within the fighting group and contribute damage or healing when enemy players die. Shared honorable kills count; you do not need the personal killing blow. Very low-level opponents and ordinary duels are not a dependable source of honorable kills.",
        "Continue until the achievement counter reaches " .. hk[2] .. ". The total is cumulative, so deaths or losing a battleground do not erase previously credited kills. Check the achievement itself rather than equating earned Honor currency with kill count.",
    }, {}, hk[1] == 238 and "One eligible honorable kill completes this first milestone. Nearby group participation can provide shared credit; ordinary duel victories are a separate achievement." or "The current Retail pages mark the 100-and-higher milestones as account-wide progress. Older comments that call all milestones through 10,000 character-only are outdated. A single character's Statistics counter can differ from this combined achievement counter.", {"https://www.wowhead.com/achievement=" .. hk[1],"https://www.wowhead.com/achievement=239#comments:id=1651744","https://www.wowhead.com/achievement=239#comments:id=2579810"}, "PvP")
end

add(245, "That Takes Class", {
    "Track the achievement and expand its class checklist. Current criteria include Death Knight, Demon Hunter, Druid, Evoker, Hunter, Mage, Monk, Paladin, Priest, Rogue, Shaman, Warlock and Warrior.",
    "Play player battlegrounds and help defeat enemy players of the missing classes. Aim to land the killing blow on an eligible opponent, as the description requests, then inspect whether that class was checked off.",
    "Repeat across matches for the classes still missing. Killing creatures, attacking a training dummy or duelling a friendly class does not replace PvP kill credit. If a class fails to credit despite a recorded killing blow, note the opponent and match for a bug report.",
}, {}, "Comments report shared honorable-kill credit, but the route does not depend on it. The old Evoker-credit complaints describe a specific Dragonflight bug; they are not evidence that the achievement was permanently retired.", {406946,598358,5507253}, "PvP")

for _, enemy in ipairs({{246,"Horde","Pandaren, Goblin, Tauren, Undead, Highmountain Tauren, Blood Elf, Orc, Troll, Nightborne and Horde Dracthyr"},{1005,"Alliance","Pandaren, Dwarf, Human, Worgen, Void Elf, Draenei, Gnome, Night Elf, Lightforged Draenei and Alliance Dracthyr"}}) do
    add(enemy[1], "Know Thy Enemy", {
        "On the opposing faction, track this achievement and expand its race checklist. The current " .. enemy[2] .. " list is: " .. enemy[3] .. ".",
        "Join player battlegrounds and participate in killing opponents of the races you still need. Aim for eligible honorable killing blows, then check the criterion after the kill instead of assuming every visually similar race is the same entry.",
        "Continue across matches until each listed race has credit. World PvP can provide a rare missing race too, but friendly duels and a player of your own faction do not satisfy this enemy-race route.",
    }, {}, "The live checklist is authoritative if criteria change. Old comments predate allied races and Dracthyr; do not stop after only the original races.", {"https://www.wowhead.com/achievement=1005#comments:id=408643"}, "PvP")
end

add(247, "Make Love, Not Warcraft", {
    "Find an opposing-faction player who is about to die, either in a player battleground or in the world. Have /hug ready on an action macro or in chat.",
    "Target the player's CORPSE immediately after death and use /hug before that player releases their spirit. A Spirit of Redemption is not the corpse required for this step.",
    "Check for achievement credit. You do not need the killing blow, an honorable kill, or even to have attacked the player; the important part is targeting the dead enemy before release.",
}, {}, "A cooperative opposite-faction friend can wait before releasing to give you time. Merely hugging a living enemy, their released bones or a spirit form is not the described action.", {334259,416365,488897,1224611}, "PvP")

for _, defender in ipairs({{388,84,71,95,"Stormwind"},{1006,85,48,80,"Orgrimmar"}}) do
    add(defender[1], "City Defender", {
        "Travel to one of your own faction's capital cities; " .. defender[5] .. " is the mapped example. Enable PvP. Keep BOTH yourself and the enemy player inside the city boundary: replies correct older claims that the victim can stand outside it. Check the location text before fighting near a gate.",
        "Help kill enemy players who enter. Deal damage yourself or participate with the defending group. Guards and other NPCs do not count; the requirement is 50 player deaths.",
        "Stay inside the city boundary while earning credit, and recheck the achievement counter after a kill. The kills are cumulative and need not happen during one invasion or one day.",
        "For a coordinated route, bring a willing opposite-faction friend and another character who can resurrect that friend. Put everyone in the same phase, kill the volunteer inside the city, resurrect them and repeat after they accept. " .. (defender[1] == 388 and "A 2026 report uses the mapped Stormwind entrance tower near 71, 95. " or "Choose a spot inside Orgrimmar where guards will not interrupt the resurrection. ") .. "Check that the first kill advances the counter before repeating; low-level volunteers can count too.",
    }, {pin(defender[2],defender[3],defender[4],1,defender[5] .. " - example city boundary; verify location text")}, "An honorable kill or personal killing blow is not required. The opposite-faction player must be attackable, so check their PvP flag and matching War Mode/phase. Holiday visitors are another opportunity. Faction-transfer and double-credit bugs are not relied on.", {"https://www.wowhead.com/achievement=388#comments:id=892121","https://www.wowhead.com/achievement=1006#comments:id=892120","https://www.wowhead.com/comment/show-replies?id=892121","https://www.wowhead.com/comment/show-replies?id=892120","https://www.wowhead.com/achievement=1006#comments:id=5388173","https://www.wowhead.com/achievement=388#comments:id=6374092"}, "PvP")
end

add(1157, "Duel-icious", {
    "Meet a willing player outside a city or another area where ordinary duels are permitted. Select them and type /duel; wait for them to accept and for the countdown.",
    "Win the duel by reducing their health to the duel's defeat threshold. Alternatively, the other player can type /forfeit after the duel begins; comments confirm that a conceded duel awards the win.",
    "Check the achievement. You do not need an arena queue, a killing blow that actually kills the player, or an opponent of your own level. You can switch roles if the other player also needs a duel win.",
}, {}, "Use an ordinary consenting duel, rather than a hostile PvP attack. Mounted Argent Tournament duels also have reported credit, but are unnecessary for this simple route.", {756572,853773,1165427}, "PvP")

for _, arena in ipairs({{397,"Step Into The Arena",1},{398,"Mercilessly Dedicated",100},{875,"Vengefully Dedicated",200},{876,"Brutally Dedicated",300}}) do
    add(arena[1], arena[2], {
        "Reach the current requirements for rated arenas and find a partner for 2v2, or two partners for 3v3. Form the appropriately sized group and open the Rated PvP panel.",
        "Choose the matching RATED arena bracket and win completed matches. Skirmishes and Training Grounds are unrated. A March 2026 reply confirms that even a 6/6 Solo Shuffle match did not advance this older arena-win counter, so use rated 2v2 or 3v3.",
        "Keep using a qualifying bracket until the achievement records " .. arena[3] .. (arena[3] == 1 and " win. Check the achievement after the result screen." or " wins. Losses slow progress but do not remove accumulated wins, and the earlier win milestones are included rather than requiring a fresh set of wins."),
    }, {}, arena[1] == 876 and "The reward is the Tabard of Brute Force. Check the achievement counter and reward mail; old comments about character-only tabard appearances predate account-wide transmog." or "These names refer to cumulative arena-win milestones. They do not require playing the original Merciless, Vengeful or Brutal season.", {"https://www.wowhead.com/achievement=876#comments","https://www.wowhead.com/comment/show-replies?id=6272472"}, "PvP")
end

for _, rating in ipairs({{399,2,1550},{400,2,1750},{401,2,2000},{1159,2,2200},{402,3,1550},{403,3,1750},{405,3,2000},{1160,3,2200}}) do
    add(rating[1], (rating[2] == 2 and "Just the Two of Us: " or "Three's Company: ") .. rating[3], {
        "Form a group of " .. rating[2] .. " players and enter the RATED " .. rating[2] .. "v" .. rating[2] .. " arena queue from the Rated PvP panel. A Solo Shuffle rating, rated battleground rating or unrated skirmish win is not this bracket's personal rating.",
        "Play completed matches and raise YOUR personal rating in that bracket to at least " .. rating[3] .. ". Inspect your character's rating after the result screen; a teammate already being above the threshold does not grant you their rating.",
        "Keep playing through wins and losses until your own rating reaches the target, then check the achievement. No exact equality is required: crossing above " .. rating[3] .. " is enough. Old arena-team purchase and team-rating instructions are obsolete.",
    }, {}, "This is a rating milestone, not a promise that a fixed number of wins will achieve it. Matchmaking rating and personal rating are different values; read the rated panel's personal bracket rating.", {"https://www.wowhead.com/achievement=402#comments:id=1395845","https://www.wowhead.com/achievement=1159#comments:id=1395874"}, "PvP")
end

for _, streak in ipairs({{408,"Hot Streak",false},{1162,"Hotter Streak",true}}) do
    add(streak[1], streak[2], {
        "Form a 2v2 or 3v3 rated arena group and track this achievement. Use actual rated arena matches; skirmishes and Solo Shuffle are not substitutes confirmed by these comment threads.",
        streak[3] and "First reach at least 1800 rating, then win ten qualifying ranked matches in a row while meeting the 1800-rating requirement. Wins before the required rating are not a safe way to build this streak." or "Win ten ranked arena matches in a row. The matches need not all be played in one sitting; stopping for the day does not itself break a winning streak.",
        "After each result, check the streak counter. A loss or draw can break the run; changing to another bracket and losing there is not a safe way to preserve progress. Continue only with teammates ready for another match.",
    }, {}, "Do not reuse the removed 5v5 bracket from early comments. Old suggestions to exploit forfeits, disconnects or team resets are unnecessary and unreliable.", {"https://www.wowhead.com/achievement=408#comments:id=564850","https://www.wowhead.com/achievement=408#comments:id=1500371","https://www.wowhead.com/achievement=1162#comments:id=1038461","https://www.wowhead.com/achievement=1162#comments:id=5511397"}, "PvP")
end

add(699, "World Wide Winner", {
    "Track the achievement's six arena criteria: Blade's Edge, Nagrand, Dalaran Sewers, Ruins of Lordaeron, Tol'Viron and Tiger's Peak.",
    "Form a group for rated 2v2 or 3v3 and queue through Rated PvP. The arena is assigned by matchmaking; travelling to a similarly named outdoor ring does not select the rated map.",
    "Win on each required arena as it appears. Repeat queued matches for missing maps and check the criterion after a win. You cannot replace a missing map with extra wins on another map.",
}, {}, "Ring of Valor was replaced in the criterion list by Tiger's Peak. Do not follow older instructions to wait for Ring of Valor to return or walk through an outdoor arena entrance.", {1878013}, "PvP")

for _, call in ipairs({908,909}) do
    add(call, "Call to Arms!", {
        "Reach the CURRENT maximum level on the character used for battlegrounds. This is not the old level-80 Call to Arms daily-quest version.",
        "Queue for player battlegrounds and stay until each match finishes. Wins and losses both count as completions; leaving early does not satisfy a completed battle.",
        "Repeat until the achievement records 100 battlegrounds completed at maximum level. Check the counter after a match if trying a new queue type; do not assume every brawl or training mode is treated identically.",
    }, {}, "Removed Call to Arms daily quests and weekend battlemaster quests are not needed. The faction counterparts describe the same 100-completion activity.", {"https://www.wowhead.com/achievement=908#comments:id=1387550","https://www.wowhead.com/achievement=908#comments:id=1661336"}, "PvP")
end

for _, rank in ipairs({{2090,"Challenger",1600},{2093,"Rival",1800},{2092,"Duelist",2100},{2091,"Gladiator",2300}}) do
    add(rank[1], rank[2], {
        "Play during an active rated PvP season. For a consistent arena route, form a 3v3 team through Group Finder and enter rated 3v3 matches. The old end-of-season battlegroup percentile system no longer describes these ranks.",
        "Raise your personal seasonal arena rating to " .. rank[3] .. ". Check the rated panel after each result; achievements for a fixed arena rating and the named seasonal rank are separate records.",
        rank[1] == 2091 and "For Gladiator, track the CURRENT season's Gladiator achievement and win 50 rated 3v3 matches at Elite rank. Midnight lowered Elite to 2300 personal rating; older 2400 instructions are outdated. Reaching the rating without the wins, or reaching it in Solo Shuffle, does not finish this Gladiator route." or "Check both the current season's rank achievement and this recurring achievement. Recent comments report the old recurring-rank credit bug was fixed in 12.0.0; if credit still fails, retain the season, bracket and rating details for a bug report.",
    }, {}, "These recurring rank achievements remain in the catalogue; expired season-specific mounts and titles are separate rewards. Rank 1's season-named Gladiator title is different from the 50-win Gladiator reward. Follow the current seasonal tracker for credited wins rather than an old season's reward page.", {"https://www.wowhead.com/achievement=2092#comments:id=6266167","https://www.wowhead.com/achievement=2091#comments:id=3245878","https://www.wowhead.com/achievement=2090#comments:id=6258865","https://worldofwarcraft.blizzard.com/en-gb/news/24266321/midnight-season-1-mythic-now-available","https://worldofwarcraft.blizzard.com/en-us/news/24244455/midnight-pre-expansion-content-update-notes"}, "PvP")
end

for _, master in ipairs({230,1175}) do
    add(master, "Battlemaster", {
        "Expand the meta and its four sub-achievements: Master of Alterac Valley, Master of Warsong Gulch, Master of Arathi Basin and Master of Eye of the Storm. Track a specific missing sub-achievement rather than only the parent title.",
        "Start the Veteran counters: win 100 matches on EACH required battleground. Pursue the smaller objectives during those matches instead of postponing all wins until last. Use the appropriate battleground queue and check credit after trying a different mode; the map selector is a reference, not a way to enter or choose a queued match.",
        "In Alterac Valley, work on the 50 graveyard assaults and 50 tower defences. Assault an enemy-held graveyard by capturing its flag; a defence means recapturing your own assaulted tower BEFORE it burns, rather than merely standing there. Bring a teammate to clear defenders. Loot eligible enemy player bodies for the Autographed Picture of Foror and Tigule. During one match, combine a graveyard assault/defence, tower assault/defence and Field of Strife kill for All-Star when opportunities arise.",
        "In Arathi Basin, combine 50 flag assaults with 50 defences. For a defence, reclaim your recently assaulted flag before enemy control completes; interrupting its original capture is not a defence. With teammates, pursue three assaults or three defences in one match, and two of each for All-Star. For Resilient Victory, your team must fall at least 500 resources behind and THEN win; organise this before the match rather than unexpectedly surrendering bases.",
        "In Warsong Gulch, build 50 flag returns and 100 enemy flag-carrier kills. Stay near your own flag with a small group: defeat the carrier, then personally click the dropped flag to return it. Five returns in one battle completes Frenzied Defender; two carrier kills before they leave your flag room completes Not In My House. For carrying objectives, ask teammates to escort you, clear the route and protect your own flag so your captures can finish.",
        "For Warsong's Quick Cap, plan a direct route and save class movement abilities and the available speed pickups before taking the flag; capture in under 75 seconds. Ironman needs three personal captures in one battle without dying. For Save the Day, defeat the enemy carrying YOUR flag in THEIR flag room while their own flag is at its base; killing a carrier elsewhere is not the same condition.",
        "In Eye of the Storm, combine 100 wins with the ten wins while holding all four bases. Coordinate base control before collecting flags. For Stormtrooper, help kill five enemy flag carriers in one battle; for Bound for Glory, make three captures without dying. Pick up the Berserker buff before securing the killing blow for Bloodthirsty Berserker. Plan the shutout and fast-win criteria with a group once the ordinary counters are nearly finished.",
        "Reopen all four masters and finish the remaining named criteria, including the Alterac mount, general-room kills and perfection conditions. Arathi's We Had It All Along now allows a winning margin of 50 resources or less, not the old exact ten-point finish. The current Alterac master does not require Alterac Blitz, and none of these four masters requires the old battleground reputation grind. Complete all four to unlock Battlemaster.",
    }, {}, "Use current child-achievement descriptions for scores and conditions: the early green lists include removed Arena Master and Strand of the Ancients requirements. Several maps have different rules in Blitz, brawls or Training Grounds, so verify the particular objective's credit before grinding a mode. The map selector shows the four battleground layouts; entry is through PvP matchmaking.", {"https://www.wowhead.com/achievement=230#comments:id=1461265","https://www.wowhead.com/achievement=1175#comments:id=439397","https://www.wowhead.com/achievement=1175#comments:id=439398","https://www.wowhead.com/comment/show-replies?id=439398","https://www.wowhead.com/achievement=1167","https://www.wowhead.com/achievement=1169","https://www.wowhead.com/achievement=1171","https://www.wowhead.com/achievement=1172","https://www.wowhead.com/achievement=162"}, "PvP")
    guides[master].areaMaps = {91,92,93,112}
end

for _, reputation in ipairs({{522,"Somebody Likes Me",1},{523,"5 Exalted Reputations",5},{524,"10 Exalted Reputations",10},{521,"15 Exalted Reputations",15},{520,"20 Exalted Reputations",20},{519,"25 Exalted Reputations",25},{518,"30 Exalted Reputations",30},{1014,"35 Exalted Reputations",35},{1015,"40 Exalted Reputations",40}}) do
    add(reputation[1], reputation[2], {
        "Track this achievement and open the Reputation panel. Start with factions already near Exalted and STOP as soon as the requested counter is reached. A different character repeating the same faction is not another distinct reputation. The longer route is a choice of missing factions, not a requirement to redo every bar.",
        "Use your faction's six home-city reputations as an initial group: buy their reputation tabards, equip ONE and clear a suitable dungeon such as The Botanica. Confirm reputation from the first kills, then finish the run, leave and reset. Swap tabards when that faction reaches Exalted.",
        "REMOVE the city tabard before farming a dungeon's own faction. Add Timbermaw Hold: complete Nafien's northern Felwood introductions, kill Deadwood furbolgs near Felpaw Village and turn in batches of five Deadwood Headdress Feathers. Use the feather turn-ins to finish the bar quickly; later Retail replies report kill reputation continuing at Revered, so there is no need to stop killing while collecting feathers.",
        "Add Sporeggar through T'shu's Sanguine Hibiscus turn-ins inside Normal Underbog, and Cenarion Expedition through Steamvault clears. For additional reputations, combine The Diplomat, Guardian of Cenarius and The Argent Champion rather than counting duplicate factions twice.",
        "For the higher targets, add the Outland dungeon factions: Sha'tar in The Botanica, Lower City in Shadow Labyrinth, Consortium in Heroic Mana-Tombs and Keepers of Time in its Caverns of Time dungeons. Add raid reputations such as Violet Eye in original Karazhan and Ashtongue Deathsworn in Black Temple between resets. Stop when the achievement's distinct-faction counter reaches " .. reputation[3] .. ".",
    }, {pin(109,71.7,55,2,"The Botanica - test equipped city tabard; Sha'tar reputation"),pin(77,64,10.4,3,"Nafien - Timbermaw introductions and feathers"),pin(77,62.5,12,3,"Felpaw Village - Deadwood feather farm"),pin(102,54.2,34.5,4,"Underbog - T'shu and Sanguine Hibiscus"),pin(102,50.4,33.3,4,"Steamvault - Cenarion Expedition"),pin(108,39.6,73.5,5,"Shadow Labyrinth - Lower City"),pin(108,39.6,57.7,5,"Heroic Mana-Tombs - Consortium"),pin(71,64.7,50,5,"Caverns of Time - Keepers of Time dungeon access"),pin(75,26.8,36.8,5,"Old Hillsbrad Foothills - Keepers of Time"),pin(75,37.2,83.3,5,"Black Morass - Keepers of Time"),pin(42,46.9,74.7,5,"Original Karazhan - Violet Eye"),pin(104,71,46.5,5,"Black Temple - Ashtongue Deathsworn")}, "Use the dedicated faction guides for their unlocks and reputation caps. Old lists include removed Zandalar Tribe/Shen'dralar grinds, Runecloth donations and pre-Cataclysm Timbermaw amounts; those methods are excluded. Spending gold is optional, and fixed completion times are not promised.", {"https://www.wowhead.com/achievement=523#comments:id=608636","https://www.wowhead.com/achievement=524#comments:id=549981","https://www.wowhead.com/achievement=1015#comments:id=1066871","https://www.wowhead.com/achievement=948#comments:id=5270034","https://www.wowhead.com/quest=28395/feathers-for-nafien"}, "Reputation")
end

for _, ambassador in ipairs({{762,"Horde","Orgrimmar, Darkspear Trolls, Thunder Bluff, Undercity, Silvermoon City and Bilgewater Cartel"},{948,"Alliance","Stormwind, Ironforge, Gnomeregan, Darnassus, Exodar and Gilneas"}}) do
