    vendorRoute[#vendorRoute + 1] = pin(109,71.7,55,3,"The Botanica - repeat city-tabard reputation runs")
    add(ambassador[1], "Ambassador of the " .. ambassador[2], {
        "Expand this achievement and check all six required factions: " .. ambassador[3] .. ". Choose an incomplete faction; its tabard lets dungeon kills raise that reputation.",
        ambassador[1] == 762 and "Buy missing tabards from Nargol, Uru'zin and Frizzo beside Orgrimmar's central flight area, Donald Adams near its southern gates, and Brave Tuho beside Thunder Bluff's flight master. For Nizara, switch to Burning Crusade Quel'Thalas through Zidormi at the southern gate, then visit her in old Eversong Woods (54.2, 50.8)." or "Buy missing tabards from Lancy Revshon beside Stormwind's flight ramp, Lasara and Candren near its Embassy, Stonehelm and Trini beside Ironforge's flight master, and Kadu beside Exodar's flight master. The map dropdown groups the vendors by city.",
        "EQUIP the reputation tabard before entering a dungeon. A compact repeatable option is Normal Botanica in Netherstorm; confirm the first kills award the selected city reputation rather than only the dungeon's native reputation.",
        "Clear the dungeon, loot, leave and reset from the portrait menu. Repeat until that city reaches Exalted, then equip the next city's tabard. If a chosen dungeon awards no city reputation, change the dungeon rather than repeating uncredited runs.",
        "Continue until all six bars are Exalted and checked in the meta. Starting-zone and other city quests can supplement a shortfall; doing a quest for one city can also give spillover to others. The title does not require Exalted with every allied-race faction.",
    }, vendorRoute, "The current checklist includes the Cataclysm city faction. Old guides listing only five cities or telling you to donate Runecloth are outdated. Spillover can stop before Exalted: equip each incomplete city's own tabard to finish its bar. Keep it equipped, rather than merely owning its appearance. If Embassy vendors are hidden by a local introduction or quest phase, finish that phase and return to the mapped vendors.", {"https://www.wowhead.com/achievement=762#comments:id=412409","https://www.wowhead.com/achievement=762#comments:id=5270008","https://www.wowhead.com/achievement=948#comments:id=5270034","https://www.wowhead.com/comment/show-replies?id=1782650","https://www.wowhead.com/npc=50484/magistrix-nizara","https://www.wowhead.com/npc=50305/moon-priestess-lasara","https://www.wowhead.com/npc=50307/lord-candren"}, "Reputation")
end

for _, diplomat in ipairs({{942,"Kurenai",54.8,70.8,"Telaar","Warden Moi'bff Jill"},{943,"Mag'har",55.8,37.8,"Garadar","Warden Bullrok"}}) do
    add(diplomat[1], "The Diplomat", {
        "Track Timbermaw Hold, Sporeggar and " .. diplomat[2] .. ". Check your current bars first; these are three separate reputations, and buying a faction's mount is not an additional requirement.",
        "Start Timbermaw at Nafien beside the northern Felwood tunnel (64.0, 10.4). Enable trivial-quest tracking and complete his Deadwood of the North and Disarming Bears introductions. Kill the hostile Deadwood around Felpaw Village and loot their Deadwood Headdress Feathers. Do not attack the friendly Timbermaw inside the tunnel.",
        "Continue the Felpaw Village circuit and hand FIVE feathers at a time to Nafien through Feathers for Nafien. Each hand-in gives 2,000 reputation before temporary bonuses. Later Retail replies confirm that kill reputation can continue at Revered, so keep killing/looting while finishing the bar. Old instructions to save hundreds of feathers or stop all kills at Revered use older values.",
        "For Sporeggar, set NORMAL difficulty, swim through Coilfang Reservoir's central pipe in Zangarmarsh and enter Underbog. Accept Bring Me A Shrubbery! from T'shu just inside. This current dungeon version needs no prior Friendly reputation with Sporeggar. Collect Sanguine Hibiscus from glowing red ground plants and creature loot; Herbalism is unnecessary.",
        "For short flower runs, clear the first ground-floor area, Hungarfen's surroundings and the path up to the first nagas, picking up every Hibiscus. Return to T'shu with at least FIVE actual flowers; a premature completed marker is not enough. Finish the first quest, then use Bring Me Another Shrubbery! repeatedly. Leave, reset Normal and repeat when flowers run out. Alternatively buy the unbound flowers from the Auction House: 280 cover Neutral to Exalted at the reported 750 reputation per five, before bonuses or kill gains. Buy less when already partway through the bar.",
        diplomat[1] == 942 and "For Kurenai, begin with Ikuti at Orebor Harborage, Zangarmarsh (41.8, 27.2), and finish the available Kurenai introductions. Continue at Telaar in Nagrand, OUTLAND, to unlock its quests and the warbead turn-in at Friendly. Do not travel to Draenor's Nagrand for this faction." or "For Mag'har, visit Nazgrel in Thrallmar's main building, Hellfire Peninsula. Follow The Assassin and its follow-ups through the Mag'har introduction, removing their initial hostility. Then continue their quests at Garadar in Nagrand, OUTLAND. This is not the Mag'har allied-race unlock or Draenor's Nagrand.",
        "Finish the available " .. diplomat[5] .. " quests to reduce the remaining grind, then kill Nagrand ogres around Laughing Skull Ruins/Ring of Blood or Warmaul Hill. Loot every corpse for Obsidian Warbeads. Other hostile Nagrand groups can give kill reputation, but the ogres also supply the repeatable turn-in item.",
        "Return to " .. diplomat[6] .. " at " .. diplomat[5] .. " and turn in sets of TEN Obsidian Warbeads for 500 reputation before bonuses. Keep alternating kills and hand-ins until " .. diplomat[2] .. " reaches Exalted. The eight ordinary reputation talbuks are optional purchases afterwards; Halaa battle tokens are unrelated to completing this reputation.",
        "Check all three Exalted criteria and select the Diplomat title when complete. Use the actual standing for how many turn-ins remain; old guides' totals include superseded reputation values and removed guild bonuses.",
    }, {pin(77,64,10.4,2,"Nafien - Deadwood of the North and Disarming Bears"),pin(77,62.5,12,2,"Felpaw Village - hostile Deadwood"),pin(77,62.5,12,3,"Felpaw Village - feather circuit"),pin(77,64,10.4,3,"Nafien - five-feather hand-ins"),pin(102,50.4,40.9,4,"Coilfang Reservoir - underwater pipe"),pin(102,54.2,34.5,4,"Underbog - T'shu is just inside"),pin(102,54.2,34.5,5,"Normal Underbog - flower runs and five-flower hand-ins"),pin(diplomat[1] == 942 and 102 or 100,diplomat[1] == 942 and 41.8 or 55,diplomat[1] == 942 and 27.2 or 36,6,diplomat[1] == 942 and "Ikuti - Orebor Harborage Kurenai introduction" or "Nazgrel - Thrallmar Mag'har introduction"),pin(107,diplomat[3],diplomat[4],6,diplomat[5] .. " - continue faction quests"),pin(107,42,23,7,"Laughing Skull Ruins - ogre and warbead search area"),pin(107,28,23,7,"Warmaul Hill - alternative ogre search area"),pin(107,diplomat[3],diplomat[4],8,diplomat[6] .. " - ten-warbead hand-ins")}, "Recent comments report Warband-wide achievement handling; inspect the meta before repeating a reputation already Exalted elsewhere. Sporeggar's current quest data displays 250, but later Retail comments consistently report 750 earned per five flowers; use the actual reputation message to calculate remaining hand-ins. Fixed farming times and old guild reputation perks are excluded.", {"https://www.wowhead.com/achievement=942#comments:id=1373822","https://www.wowhead.com/comment/show-replies?id=1373822","https://www.wowhead.com/achievement=942#comments:id=6063095","https://www.wowhead.com/achievement=943#comments:id=619827","https://www.wowhead.com/comment/show-replies?id=619827","https://www.wowhead.com/achievement=943#comments:id=899749","https://www.wowhead.com/comment/show-replies?id=1324862","https://www.wowhead.com/quest=29691#comments:id=5671134","https://www.wowhead.com/quest=29692#comments:id=2317891","https://www.wowhead.com/quest=29692#comments:id=6038363","https://www.wowhead.com/npc=18008/ikuti"}, "Reputation")
end

add(945, "The Argent Champion", {
    "Track BOTH Argent Dawn and Argent Crusade. These are separate factions on separate continents. Skip a completed Exalted bar; otherwise begin with the Dawn introduction below.",
    "At Fiona's caravan beside Eastern Plaguelands' western bridge (9.0, 66.0), complete BOTH companion chains: Gidwin Goldbraids -> Just Encased -> Greasing the Wheel, and Tarenar Sunstrike -> What I Do Best -> A Gift for Fiona. Enable trivial-quest tracking if you are above the zone's level.",
    "Take Onward, to Light's Hope Chapel and ride to Crown Guard Tower. Pick up Traveling Companions at the TOP of the tower and complete Rough Roads. Continue with The Trek Continues and Fiona's Boys Will Be Boys, then A Boyhood Dream -> Argent Call: The Trial of the Crypt at Light's Hope Chapel. Finish this introduction even if an old character is already Revered but cannot see Raymond's quests.",
    "Visit Lord Raymond George BEHIND Light's Hope Chapel (76.0, 51.0). Accept Annals of the Silver Hand. Set Normal difficulty and enter Stratholme's MAIN Gate (27.1, 11.6), not its Service Entrance. Follow the living/Crusader's Square route into the western Scarlet stronghold toward Balnazzar's Crimson Throne.",
    "Find Instructor Galford's room opposite the final throne room. Loot the Annals book from the table beside him, around 27.3, 74.9 on the Stratholme MAIN GATE interior map. You need the quest in your log to collect this book; clearing the whole dungeon again is unnecessary.",
    "Return the book to Raymond for 2,000 base Argent Dawn reputation and ACCEPT ANNALS AGAIN before leaving. Return to the same cleared instance for another book. Do not reset it: the book remains lootable even if its minimap quest marker disappears. Eleven hand-ins cover 0/21,000 Revered to Exalted before bonuses. Setting your hearthstone at Light's Hope can shorten the return trip when available.",
    "For Argent Crusade, do its Argent Vanguard introductions in southeastern Icecrown if below Friendly. At Friendly, buy Tabard of the Argent Crusade from Veteran Crusader Aliocha Segard there (87.5, 75.6), and EQUIP it. The similarly named Argent Crusader's Tabard is a different item and does not champion this reputation.",
    "Fly to the EASTERN dungeon portal beside Ulduar in The Storm Peaks (45.3, 21.6): Halls of Lightning. Clear it with the tabard equipped and check the first kills award Argent Crusade reputation. Heroic gives more reputation but boss kills have a daily lockout; Normal gives less and can be left and reset repeatedly. Use Normal for repeat runs rather than trying to reset a saved Heroic.",
    "Continue the tabard runs to Exalted. Check that both the Dawn and Crusade criteria are credited, then select the Argent Champion title. Old Scourgestones, an Argent Dawn Commission and the removed original Naxxramas attunement are not prerequisites for these routes.",
}, {pin(23,9,66,2,"Fiona - both companion introductions"),pin(23,76,51,3,"Light's Hope - finish the crypt trial"),pin(23,76,51,4,"Lord Raymond George - accept Annals"),pin(23,27.1,11.6,4,"Stratholme MAIN Gate - enter here"),pin(317,27.3,74.9,5,"Galford's table - Annals of the Silver Hand","Stratholme - Main Gate"),pin(23,76,51,6,"Raymond - return book and reaccept"),pin(23,27.1,11.6,6,"Return to the cleared MAIN Gate instance"),pin(317,27.3,74.9,6,"Collect another book without resetting","Stratholme - Main Gate"),pin(118,87.5,75.6,7,"Argent Vanguard - introductions and Aliocha's tabard"),pin(120,45.3,21.6,8,"Halls of Lightning - EASTERN Ulduar dungeon portal")}, "The book shortcut has later Retail confirmations in 2024 and 2025. Its prerequisites are quest completion, not simply reaching Revered. Keep temporary reputation bonuses if available, but old guild reputation perks and the former Human reputation racial are excluded from the turn-in count.", {1347343,3176313,5424389,"https://www.wowhead.com/comment/show-replies?id=1347343","https://www.wowhead.com/quest=28755#comments:id=1370979","https://www.wowhead.com/comment/show-replies?id=1370979","https://www.wowhead.com/quest=28755#comments:id=1206964","https://www.wowhead.com/comment/show-replies?id=1206964","https://www.wowhead.com/quest=28755#comments:id=1369513","https://www.wowhead.com/quest=28755#comments:id=1571320","https://www.wowhead.com/npc=30431/veteran-crusader-aliocha-segard","https://www.wowhead.com/item=43154/tabard-of-the-argent-crusade","https://us.forums.blizzard.com/en/wow/t/cannot-earn-argent-crusader-rep-wearing-tabard/1866155"}, "Reputation")

-- Preserve and relocate the already curated Cenarion route from the BC module.
add(953, "Guardian of Cenarius", {
    "Track BOTH Cenarion Expedition and Cenarion Circle. They are different factions on different continents; Exalted with only one is insufficient. Check which bar still needs reputation.",
    "For Cenarion Expedition, fly to Coilfang Reservoir in Zangarmarsh (50.3, 40.8). Swim through the central pipe and enter the Steamvault portal in the cavern. Clear trash and bosses; activate the panels after Thespia and Steamrigger to open Kalithresh's room.",
    "Repeat Normal Steamvault while kills award reputation. If Normal kills stop just below Exalted, finish with Heroic Steamvault, Slave Pens or Underbog, or remaining Expedition quests. The old Coilfang Armament turn-in is unavailable.",
    "For Cenarion Circle without waiting for raid resets, buy Encrypted Twilight Texts (item 20404) from the Auction House. You need ten per hand-in. From exactly 0/3,000 Neutral, 840 texts cover the full 42,000 reputation at 500 per ten; buy fewer if already partway through the bar or using a temporary reputation bonus. Compare the total cost before buying.",
    "Travel to Silithus. If Cenarion Hold is missing because the zone shows Sargeras' wound, speak to Zidormi near Valor's Rest in the northeastern corner (78.8, 22.0), on top of the cliff, and select Silithus BEFORE the wound. This old phase remains accessible in Retail.",
    "Find Bor Wildmane beside the moonwell in Cenarion Hold (53.2, 35.0). Complete Secret Communication with your first TEN texts to unlock Encrypted Twilight Texts. Accept, turn in and reaccept that repeatable quest with each next set of ten until Exalted. Bring the actual texts in your bags; you do not need windstone summons or cultist clothing.",
    "For a route without buying texts, enter the RUINS of Ahn'Qiraj, the smaller raid beyond southern Silithus's Scarab Wall. Clear elite trash and bosses, including Rajaxx's waves, instead of rushing only to Ossirian. These kills provide Cenarion Circle reputation through Exalted. Repeat after its raid lockout resets; do not use the Temple of Ahn'Qiraj as the same clear.",
    "Finish whichever bar remains: repeat the Circle text hand-ins or return for another Ruins lockout, and complete remaining Expedition Heroics after their resets. Verify BOTH factions are Exalted. The Cenarion War Hippogryph is an optional purchase afterward, not a title requirement.",
}, {pin(102,50.3,40.8,2,"Coilfang Reservoir - underwater pipe"),pin(102,50.4,33.3,2,"Steamvault portal inside reservoir"),pin(102,48.9,35.6,3,"Slave Pens - additional Heroic reputation"),pin(102,54.2,34.6,3,"Underbog - additional Heroic reputation"),pin(81,78.8,22,5,"Zidormi - return Silithus to before the wound"),pin(81,53.2,35,6,"Bor Wildmane - first and repeat ten-text hand-ins"),pin(81,36,84.7,7,"Scarab Wall - approach the RUINS portal")}, "Twilight Text hand-ins can finish Cenarion Circle without waiting for another Ruins lockout. Reputation bonuses reduce the number needed, so check the bar before buying another stack. Use Steamvault and the additional Heroics for Expedition. Old Windstone summons and Coilfang Armament turn-ins are unavailable.", {965814,2460500,3244934,"https://www.wowhead.com/comment/show-replies?id=3244934","https://www.wowhead.com/zone=3429/ruins-of-ahnqiraj","https://www.wowhead.com/quest=8319#comments:id=5542755","https://www.wowhead.com/comment/show-replies?id=5542755","https://www.wowhead.com/quest=8319#comments:id=5191775","https://www.wowhead.com/comment/show-replies?id=5191775","https://www.wowhead.com/npc=15306/bor-wildmane","https://www.wowhead.com/npc=128607/zidormi"}, "Reputation")

add(545, "Shave and a Haircut", {
    "Visit a Retail barbershop. Alliance can use the shop behind Stormwind's Trade District Auction House (61.4, 64.6); Horde can use the shop above Orgrimmar's Valley of Strength (40.8, 60.8). Look for the striped barber pole.",
    "Click an empty barber CHAIR to open customization. Choose a different available hairstyle or hair colour so there is an actual change to apply.",
    "Confirm the changes, then check achievement credit. Closing the preview without applying does not complete the visit. If you are a Worgen, customize the Worgen form if a human-form change fails to credit.",
}, {pin(84,61.4,64.6,1,"Stormwind barbershop - click the chair"),pin(85,40.8,60.8,1,"Orgrimmar barbershop - above Valley of Strength")}, "The old level-based gold prices and temporary free-haircut exploits in comments are obsolete. Use the current barbershop's confirmation button.", {566816,1247630,1675793,2302094,"https://www.wowhead.com/npc=29142/jelinek-sharpshear","https://www.wowhead.com/npc=29143/bebri-coifcurl"}, "Other")

for _, tabards in ipairs({{621,"Represent",1},{1020,"Ten Tabards",10},{1021,"Twenty-Five Tabards",25}}) do
    local tabardPins = {
        pin(84,64,77.2,2,"Rebecca Laughlin - Guild Tabard and eligible older tabards"),
        pin(85,47.6,75.6,2,"Garyl - Guild Tabard and eligible older tabards"),
        pin(118,87.5,75.6,3,"Aliocha Segard - Argent Crusade tabard at Friendly"),
        pin(125,25.6,47.8,3,"Archmage Alvareaux - Kirin Tor tabard at Friendly"),
        pin(115,59.8,53,3,"Cielstrasza - Wyrmrest tabard; top of temple"),
        pin(118,43.4,20.6,3,"Duchess Mynx - Ebon Blade tabard; unlock Shadow Vault"),
        pin(198,62.8,23.8,4,"Provisioner Whitecloud - inside Nordrassil inn"),
        pin(205,49,42,4,"Provisioner Arok - Silver Tide Hollow cave"),
        pin(249,54,33.2,4,"Blacksmith Abasi - Ramkahen tabard","Uldum (Cataclysm)"),
        pin(207,56.8,13.2,4,"D'lom the Collector - finish Therazane introductions"),
        pin(241,48.6,30.6,4,"Craw MacGraw - Alliance Wildhammer tabard"),
        pin(241,53.8,42,4,"Grot Deathblow - Horde Dragonmaw tabard"),
        pin(84,64,77.2,5,"Rebecca Laughlin - unlocked Outland reputation tabards"),
        pin(85,47.6,75.6,5,"Garyl - unlocked Outland reputation tabards"),
        pin(102,17.8,51.2,5,"Sporeggar - collect ten Glowcaps nearby for its tabard"),
        pin(84,64,77.2,6,"Rebecca Laughlin - four old Alliance PvP tabards"),
        pin(85,47.6,75.6,6,"Garyl - four old Horde PvP tabards"),
    }
    -- Reuse the researched city quartermasters, with this guide's step number.
    for _, ambassadorID in ipairs({762,948}) do
        for _, waypoint in ipairs(guides[ambassadorID].waypoints) do
            if waypoint.step == 2 then
                tabardPins[#tabardPins + 1] = {mapID = waypoint.mapID, x = waypoint.x, y = waypoint.y, step = 2, label = waypoint.label, mapName = waypoint.mapName}
            end
        end
    end
    add(tabards[1], tabards[2], {
        "Open Appearances > Tabards and track this achievement. Learn " .. tabards[3] .. " distinct qualifying appearances, checking the counter after each purchase. Stop as soon as the target is met; the later batches below are alternatives for larger collections. Extra copies of one tabard are not extra entries.",
        "Start with your faction's six basic city tabards from the mapped quartermasters; the Ambassador guide uses the same vendor route. Buy the inexpensive silver-priced city tabards rather than paying Champion's Seals at the Argent Tournament. Add a standard Guild Tabard from Rebecca Laughlin in Stormwind or Garyl in Orgrimmar. Equip purchased tabards to make their appearances permanent. These provide up to seven entries.",
        "Add the four Northrend tabards at Friendly reputation: Argent Crusade from Aliocha Segard, Kirin Tor from Archmage Alvareaux, Wyrmrest Accord from Cielstrasza on top of Wyrmrest Temple, and Ebon Blade from Duchess Mynx. Quest for a missing Friendly reputation; Mynx also needs the Shadow Vault quest hub unlocked. This brings the suggested collection to eleven.",
        "Add five Cataclysm tabards at Friendly: Guardians of Hyjal from Whitecloud inside Nordrassil inn; Earthen Ring from Arok in the Silver Tide Hollow underwater cave; Ramkahen from Abasi; Therazane from D'lom; and your faction's Wildhammer or Dragonmaw tabard from Craw MacGraw or Grot Deathblow. Complete the corresponding zone introductions if the faction/vendor is still locked, especially Therazane's Deepholm chain. These bring the suggested total to sixteen.",
        "For five more, finish Cenarion Expedition, Sporeggar, Lower City, Sha'tar and Keepers of Time reputations to Exalted, then buy their tabards from Rebecca or Garyl's eligible stock. Use the individual reputation guides for the grinds. Sporeggar's tabard costs ten Glowcaps, so gather those mushrooms around Sporeggar or check the Auction House before visiting the shared vendor. Existing Outland tabards you already own can replace any missing choice.",
        "If still short, Rebecca or Garyl sells four old PvP tabards: Private's Tabard/Scout's Tabard, Knight's Colors/Stone Guard's Herald, Stormpike/Frostwolf Battle Tabard and Silverwing/Warsong Battle Tabard. Their current listed prices are one, one, ten and ten Marks of Honor respectively. Buy missing ones, equip them and keep each permanent unlock. With the preceding batches, these supply a complete 25-tabard route without a retired event reward or random drop.",
        tabards[1] == 1021 and "At 25, check your mail for Tabard of the Achiever. If already earned on the account, speak to a tabard vendor about replacing it on this character." or "Check this achievement once the requested count is reached. Continue only if you also want the larger tabard milestones.",
    }, tabardPins, "The wardrobe change supersedes the old collection macros. Later-expansion tabards do not all advance this older counter, so the route uses the established original, Outland, Northrend and Cataclysm choices. Refunds can remove an appearance; do not copy the old buy-and-refund trick. The seven-entry city/guild batch is an upper total if none was already collected.", {"https://www.wowhead.com/achievement=621#comments:id=1690191","https://www.wowhead.com/achievement=621#comments:id=2448733","https://www.wowhead.com/achievement=1021#comments:id=1408204","https://www.wowhead.com/comment/show-replies?id=1408204","https://www.wowhead.com/achievement=1021#comments:id=3215854","https://www.wowhead.com/npc=5193/rebecca-laughlin","https://www.wowhead.com/npc=5188/garyl","https://www.wowhead.com/item=65906/tabard-of-the-guardians-of-hyjal","https://www.wowhead.com/item=65905/tabard-of-the-earthen-ring","https://www.wowhead.com/item=65904/tabard-of-ramkahen","https://www.wowhead.com/item=65907/tabard-of-therazane","https://www.wowhead.com/item=65908/tabard-of-the-wildhammer-clan","https://www.wowhead.com/item=65909/tabard-of-the-dragonmaw-clan"}, "Collections")
end

for _, pet in ipairs({{1017,"Can I Keep Him?",1},{15,"Plenty of Pets",15},{1248,"Plethora of Pets",25},{1250,"Shop Smart, Shop Pet...Smart",50},{2516,"Lil' Game Hunter",75}}) do
    add(pet[1], pet[2], {
        "Open the Pet Journal and track this achievement. Collect " .. pet[3] .. " DIFFERENT pet species; three copies of one species do not become three unique pets. Stop when the requested count is reached. Use the nearby vendor batch first, and the later batches only for entries you still need.",
        "Alliance vendor batch: buy Bombay, Cornish Rex, Orange Tabby and Silver Tabby cats from Donni Anthania in Elwynn Forest; both owl species from Shylenai in Stormwind's northern refugee area; Snowshoe Rabbit from Yarlyn Amberstill in Dun Morogh; and Blue, White and Yellow Moths from Sixx in the Exodar. These are ten different species. USE every carrier/egg to learn the pet; a closed carrier in your bags is not collected.",
        "Horde vendor batch: buy Black Kingsnake, Brown Snake and Crimson Snake from Xan'tish, who walks through Orgrimmar's Valley of Spirits; Prairie Dog from Halpa in Thunder Bluff; and Golden, Red and Silver Dragonhawks from Jilanne in the BURNING CRUSADE version of Eversong Woods. Use the past Quel'Thalas phase to reach Jilanne. Pets learned on an eligible faction alt join the same account journal, so no old neutral-Auction-House transfer is needed.",
        "Neutral vendor batch: visit Dealer Rashaad beside the Stormspire inn in Netherstorm (43.5, 35.2). Buy missing Brown Rabbit, Cockroach, Crimson Snake, Mana Wyrmling, Red Moth, Senegal, Siamese Cat and Blue Dragonhawk Hatchling. Crimson Snake overlaps Xan'tish's stock, so skip a duplicate rather than counting it twice.",
        "Add Cockatiel from Narkk in Booty Bay (42.6, 69.2, Cape of Stranglethorn). For Ancona Chicken, go to Tirth's Haunt in southeastern Thousand Needles (85.4, 91.4), right-click the running chicken named Plucky Johnson and buy while he is human; interact again if he transforms back. Do not follow the old Magus Tirth vendor directions to the submerged pre-Cataclysm race track. The combined vendor batches can supply 26 different species.",
        "For the remaining count, browse Auction House > Battle Pets and compare the species with your Journal's Not Collected list before buying. Pick inexpensive LEVEL 1 cages you can learn; a higher-level caged pet can be unusable until you have already levelled a pet that high yourself. Loot purchases from mail, right-click each cage to learn it, then check the achievement. Rarity and breed are irrelevant when collecting a new species.",
        "For a gold-saving alternative, learn Battle Pet Training from Audrey Burnhep in Stormwind (69.2, 25.0) or Varzok in Orgrimmar (52.6, 58.8). Put a battle-ready pet in the first team slot and enable Track Pets. Start against low-level wild pets around Goldshire in Elwynn Forest or Razor Hill in Durotar, then follow the trainer's introductory battles as your team levels.",
        "To capture a missing wild species, start its pet battle, reduce its health below 35% without killing it, then use Trap until successful and finish the battle. Look for green paw markers and check the species tooltip before fighting. Capture new names as you move through zones; an extra breed or colour of the SAME species is not another entry. Buying pets is optional if you prefer to complete the remaining collection through captures.",
        "Continue until the counter reaches " .. pet[3] .. (pet[1] == 1250 and ". Then inspect the Pet Journal for Stinker, the milestone's reward." or pet[1] == 2516 and ". Then inspect the Pet Journal for Little Fawn; later comments say the reward is added directly rather than always arriving in mail." or ". Learning the item is essential; merely keeping an unused carrier or cage in your bags is insufficient."),
    }, {pin(37,44.2,53.4,2,"Donni Anthania - four different cats"),pin(84,56,3.4,2,"Shylenai - two owls; northern refugee area"),pin(27,70.4,49.2,2,"Yarlyn Amberstill - Snowshoe Rabbit"),pin(103,30.4,34.6,2,"Sixx - three moth species"),pin(85,33.4,65,3,"Xan'tish - walking snake vendor; search nearby"),pin(88,62.8,58.4,3,"Halpa - Prairie Dog"),pin(94,44.8,71.6,3,"Jilanne - three dragonhawks","Eversong Woods (Burning Crusade)"),pin(109,43.5,35.2,4,"Dealer Rashaad - upper Stormspire, beside inn"),pin(210,42.6,69.2,5,"Narkk - Cockatiel"),pin(64,85.4,91.4,5,"Plucky Johnson - Ancona Chicken"),pin(84,69.2,25,7,"Audrey Burnhep - Battle Pet Training"),pin(85,52.6,58.8,7,"Varzok - Battle Pet Training"),pin(37,42.2,65.8,7,"Goldshire - nearby low-level wild-pet search"),pin(1,51.8,43.4,7,"Razor Hill - nearby low-level wild-pet search")}, "Use the achievement's distinct-species counter rather than a Journal total inflated by duplicates. Basic vendor pets can be learned without a pet-battle team. Stinker/Little Fawn may appear directly in the Journal; relog once if the achievement is complete but its reward is missing. Retired promotional pets and real-money purchases are unnecessary.", {"https://www.wowhead.com/achievement=15#comments:id=424584","https://www.wowhead.com/comment/show-replies?id=424584","https://www.wowhead.com/achievement=1248#comments:id=424586","https://www.wowhead.com/achievement=1250#comments:id=404589","https://www.wowhead.com/comment/show-replies?id=404589","https://www.wowhead.com/achievement=1250#comments:id=1759217","https://www.wowhead.com/achievement=2516#comments:id=1838578","https://www.wowhead.com/npc=20980/dealer-rashaad","https://www.wowhead.com/npc=41135/plucky-johnson","https://www.wowhead.com/guide/battle-pets/getting-started"}, "Collections")
end

