for _, mount in ipairs({{2141,"Stable Keeper",10},{2142,"Filling Up The Barn",25},{2143,"Leading the Cavalry",50},{2536,"Mountain o' Mounts",100},{2537,"Mountain o' Mounts",100}}) do
    local mountPins = {
        pin(37,84,65.5,3,"Katie Hunter - six horses, Eastvale Logging Camp"),pin(56,9.2,56.4,3,"Unger Statforth - additional Black Stallion"),
        pin(27,70.5,49,3,"Veron Amberstill - six rams"),pin(27,56.2,46.2,3,"Milli Featherwhistle - seven mechanostriders"),
        pin(84,55.6,12.6,3,"Lelanai - seven sabers, northern refugee area"),pin(84,52.6,8.2,3,"Astrid Langstrump - two mountain horses"),
        pin(103,81.4,52,3,"Torallius - six elekks, just outside Exodar's main exit"),
        pin(85,61.6,35.4,4,"Ogunaro Wolfrunner - seven wolves"),pin(85,36.2,86.6,4,"Kall Worthaton - two trikes"),
        pin(1,55.2,75.5,4,"Zjolnir - six raptors, Sen'jin Village"),pin(7,47.5,58.2,4,"Harb Clawhoof - six kodos"),
        pin(18,61.8,51.8,4,"Zachariah Post - seven skeletal horses; past Tirisfal"),
        pin(18,69.5,62.8,4,"Zidormi - pre-battle Tirisfal for Brill's vendor"),
        pin(94,61,54.6,4,"Winaestra - seven hawkstriders; past Quel'Thalas","Eversong Woods (Burning Crusade)"),
        pin(23,53.8,8.6,4,"Zidormi - Burning Crusade Quel'Thalas for Winaestra"),
        pin(84,68,17.6,5,"Adherent Hanjun - Tushui tabard"),pin(84,67.6,18.6,5,"Old Whitenose - twelve dragon turtles"),
        pin(85,68.6,40.6,5,"Disciple Jusi - Huojin tabard"),pin(85,69.6,41.6,5,"Turtlemaster Odai - twelve dragon turtles"),
        pin(125,58,42.4,6,"Mei Francis - seven ordinary flyers and additional mounts"),
        pin(107,54.5,75.1,7,"Trader Narasu - eight Kurenai talbuks"),pin(107,53.5,36.9,7,"Provisioner Nasela - eight Mag'har talbuks"),
        pin(108,64.2,66.2,8,"Grella - five nether rays at Exalted"),pin(104,65.6,86,8,"Drake Dealer Hurlunk - remaining Netherwing colours"),
    }
    local mountSteps = {
        "Track this achievement on the character with your highest mount counter. The target is " .. mount[3] .. " mounts usable for this milestone. In the Mount Journal, enable Not Collected to identify missing colours; its overall total can include opposite-faction variants that do not add to this counter. Stop the route as soon as you reach your target.",
        "Start with racial mount vendors. A character of the vendor's own race can normally buy its mounts without an Exalted grind; learn them on an eligible permanent alt, then log back into your collector. Other races need Exalted with that city. If a vendor refuses, check the character's race, reputation and item requirements; for example, Lightforged Draenei do not receive the ordinary Draenei exemption.",
        "ALLIANCE route: Katie Hunter at Eastvale Logging Camp sells six horses; Unger Statforth at Menethil Harbor adds Black Stallion. Veron Amberstill sells six rams and Milli Featherwhistle seven mechanostriders in Dun Morogh. In northern Stormwind, buy seven sabers from Lelanai and two mountain horses from Astrid Langstrump. Torallius, just outside Exodar's main exit, sells six elekks. These batches offer 35 different mounts; buy only colours you have not learned.",
        "HORDE route: buy seven wolves from Ogunaro Wolfrunner and two trikes from Kall Worthaton in Orgrimmar; six raptors from Zjolnir in Sen'jin Village; six kodos from Harb Clawhoof in Bloodhoof Village; seven skeletal horses from Zachariah Post at Brill; and seven hawkstriders from Winaestra at Thuron's Livery. These batches also offer 35 mounts. Use Zidormi's past Tirisfal/Quel'Thalas phases if the old vendors are absent. Buying the other faction's counterpart colours does not double your achievement progress.",
        "Add twelve dragon turtles: six normal colours and their six Great versions. Alliance uses Old Whitenose beside Stormwind's lake; Horde uses Turtlemaster Odai in Orgrimmar. Use a Pandaren of your faction, or earn Exalted with Tushui/Huojin by wearing the nearby quartermaster's tabard in eligible dungeons. Check the first reputation gain before repeating runs. Different item IDs teaching the SAME turtle are not extra mounts; check Already Known before buying.",
        "Visit Mei Francis in NORTHREND Dalaran (58.0, 42.4). Buy your seven ordinary gryphon/wind rider colours if missing, then compare the Armored Brown Bear and Armored Snowy Gryphon/Armored Blue Wind Rider with your remaining budget. You do not need the expensive Traveler's Tundra Mammoth. Use every reins item to LEARN it; unused items in your bags do not build the learned-mount counter.",
        "For eight more mounts, reach Exalted with Kurenai or Mag'har in OUTLAND Nagrand. Finish their introductory quests, then kill Nagrand ogres and turn in Obsidian Warbeads using The Diplomat route. Buy all four Riding Talbuk colours AND all four War Talbuk colours from Trader Narasu in Telaar or Provisioner Nasela in Garadar. These eight do not require Halaa battle tokens.",
        "For eleven more, reach Sha'tari Skyguard Exalted and buy Grella's five nether rays at Blackwind Landing; complete the Netherwing introduction and reputation grind for six Netherwing drake colours. The first drake is a quest reward; buy the other five from Drake Dealer Hurlunk on Netherwing Ledge. Use their individual mount guides for the unlock quests. Only one free reward does not mean only one colour can be learned.",
    }
    if mount[3] == 100 then
        mountSteps[#mountSteps + 1] = "For the remaining gap to 100, choose missing vendor batches instead of waiting for rare drops: five faction war mounts from Lieutenant Karter/Raider Bork (Marks of Honor); Cenarion War Hippogryph from Fedryen Swiftspear at Cenarion Expedition Exalted; Red Drake from Cielstrasza at Wyrmrest Accord Exalted; two mammoths from Lillehoff after the Sons of Hodir introduction and required reputations; and two ordinary riding camels from Blacksmith Abasi at Ramkahen Exalted. Read current prices: old battleground marks, Justice Points and Stone Keeper's Shards are obsolete. Check the individual mount guides before starting a reputation from scratch."
        mountSteps[#mountSteps + 1] = "The Argent Tournament supplies another large permanent batch if you still need mounts. Start with Justicar Mariel Trueheart at the Icecrown tournament grounds. Complete the jousting training, Aspirant and Valiant dailies through your city's Champion trial; keep doing Champion dailies for Champion's Seals. Champion the other cities in turn to open their quartermasters. Prioritise each city's mount costing five seals plus gold before saving for its 100-seal mount. This unlock takes daily resets; the vendors are inside the faction pavilions at the mapped grounds."
        mountPins[#mountPins + 1] = pin(84,76.2,65.6,9,"Lieutenant Karter - Alliance war-mount batch")
        mountPins[#mountPins + 1] = pin(85,41.8,72.6,9,"Raider Bork - Horde war-mount batch")
        mountPins[#mountPins + 1] = pin(102,79.2,63.8,9,"Fedryen Swiftspear - Cenarion War Hippogryph")
        mountPins[#mountPins + 1] = pin(115,59.8,53,9,"Cielstrasza - Red Drake; top of Wyrmrest Temple")
        mountPins[#mountPins + 1] = pin(120,66,61.5,9,"Lillehoff - Sons of Hodir mammoths; finish introduction")
        mountPins[#mountPins + 1] = pin(249,54,33.2,9,"Blacksmith Abasi - two Ramkahen camels")
        mountPins[#mountPins + 1] = pin(118,69.6,22.8,10,"Justicar Mariel Trueheart - Argent Tournament introduction")
        mountPins[#mountPins + 1] = pin(118,76.4,19.4,10,"Alliance tournament pavilion - city mount quartermasters")
        mountPins[#mountPins + 1] = pin(118,76.4,24.4,10,"Horde tournament pavilion - city mount quartermasters")
    end
    mountSteps[#mountSteps + 1] = "Recheck the achievement after learning each batch. If progress stalls despite new mounts, log the character with your highest usable count, open its Mount Journal and learn another missing mount if necessary. At 50, inspect the Journal for Albino Drake; at 100, inspect it for your faction's Dragonhawk. Later comments report these rewards are added directly, so do not wait only for a letter."
    add(mount[1], mount[2], mountSteps, mountPins, "Stop at your target; the later reputation batches are unnecessary for the 10/25 milestones. Temporary Magic Brooms do not count. Racial size restrictions, removed cloth donations and old profession-switching advice are obsolete. Use the achievement counter for class/profession edge cases rather than treating every historical comment as current. This route needs no retired seasonal or promotional mount.", {"https://www.wowhead.com/achievement=2141#comments:id=415066","https://www.wowhead.com/achievement=2142#comments:id=591479","https://www.wowhead.com/achievement=2143#comments:id=394355","https://www.wowhead.com/achievement=2143#comments:id=1760823","https://www.wowhead.com/achievement=2536#comments:id=863999","https://www.wowhead.com/comment/show-replies?id=573538","https://www.wowhead.com/comment/show-replies?id=1443836","https://www.wowhead.com/achievement=2537#comments:id=1707186","https://www.wowhead.com/comment/show-replies?id=5976366","https://www.wowhead.com/npc=65068/old-whitenose","https://www.wowhead.com/npc=66022/turtlemaster-odai","https://www.wowhead.com/npc=32216/mei-francis","https://www.wowhead.com/npc=17584#comments:id=5925312"}, "Collections")
end

add(727, "Call in the Cavalry", {
    "Earn Marks of Honor through available player PvP rewards, then visit Lieutenant Karter outside Champions' Hall in Stormwind (76.2, 65.6), or Raider Bork above Orgrimmar's Valley of Strength (41.8, 72.6). These are the old war-mount vendors.",
    "Buy ONE qualifying mount from the achievement list, such as Black War Steed or Black Battlestrider for Alliance, or Black War Wolf or Black War Kodo for Horde. Read the vendor's current price; the 2008 battleground-mark and later 2,000-Honor prices are obsolete.",
    "Use the purchased mount item to learn it, then check the achievement. You do not need all ten faction mounts. A Black War Mammoth, Dark War Talbuk or Alterac Valley mount is not a replacement for one of the listed ten.",
}, {pin(84,76.2,65.6,1,"Lieutenant Karter - Alliance war mounts"),pin(85,41.8,72.6,1,"Raider Bork - Horde war mounts")}, "Learn the mount rather than returning the unused item. Only one qualifying war mount is needed for this achievement.", {407177,768797,1350399,1420285,"https://www.wowhead.com/npc=12783/lieutenant-karter","https://www.wowhead.com/npc=12796/raider-bork"}, "Collections")

for _, freedom in ipairs({{700,"Horde",85,38.2,72.6,"First Sergeant Hola'mahi"},{701,"Alliance",84,75.4,67,"Sergeant Major Clate"}}) do
    local isHorde = freedom[1] == 700
    local fortGiver = isHorde and "Battlecryer Blackeye in Thrallmar (55.8, 39.0)" or "Warrant Officer Tracy Proudwell in Honor Hold (56.4, 62.8)"
    add(freedom[1], "Freedom of the " .. freedom[2], {
        "On a " .. freedom[2] .. " character, inspect the old PvP vendor " .. freedom[6] .. ". Find the ORIGINAL Insignia of the " .. freedom[2] .. " that matches your class, rather than a modern PvP medallion with a similar effect.",
        "Check the item tooltip's class restriction and current Honor price, then buy the eligible insignia. Keep it in your bags and check achievement credit; if the award is delayed, relog once with the item still owned.",
        "For an alternative without an Honor purchase, visit " .. fortGiver .. " in OUTLAND Hellfire Peninsula. Take the ORIGINAL Hellfire Fortifications quest (" .. (isHorde and "13409" or "13408") .. "), whose reward includes Insignia of the " .. freedom[2] .. ". Its later daily version does not award that insignia. If it is unavailable, finish " .. (isHorde and "the initial Thrallmar chain through Felspark Ravine and Forward Base: Reaver's Fall." or "The Legion Reborn, The Path of Anguish and Expedition Point from Honor Hold's initial chain."),
        "Enable PvP and stand on the ground, out of stealth, inside each fortification: the Overlook around 40, 48, the Stadium around 35, 50 and Broken Hill around 40, 56. Wait for its capture bar to reach your faction and for the quest objective to tick. A fort already owned by your faction cannot be captured again until the opposition takes it or makes it neutral; arrange a willing opposite-faction helper if needed. Both characters must use the same phase/War Mode setting.",
        "Return to the quest giver, choose the insignia and keep it in your bags. Relog once if the achievement does not immediately appear. An October 2026 reply confirms the Hellfire quest route still grants this Legacy achievement; no enemy-player kill is required for an uncontested tower capture.",
        "If the original quest is already completed and you lack an eligible vendor insignia, obtain a Vicious Gladiator's medallion from Argaloth in Baradin Hold. This is random loot and may need more than one reset; the raid is entered only while your faction controls Tol Barad.",
    }, {pin(freedom[3],freedom[4],freedom[5],1,freedom[6] .. " - original class insignias"),pin(100,isHorde and 55.8 or 56.4,isHorde and 39 or 62.8,3,fortGiver .. " - original insignia quest"),pin(100,40,48,4,"The Overlook - PvP capture area"),pin(100,35,50,4,"The Stadium - PvP capture area"),pin(100,40,56,4,"Broken Hill - PvP capture area"),pin(100,isHorde and 55.8 or 56.4,isHorde and 39 or 62.8,5,"Hellfire Fortifications - choose and keep the insignia"),pin(244,46,48.8,6,"Baradin Hold - alternative Argaloth medallion loot")}, "Use the original insignia or a specifically confirmed medallion. Heirloom insignias and every later season's medallion do not necessarily qualify. Tower ownership can require waiting or help from the opposite faction; enable the PvP flag before entering its capture area if the bar does not appear.", {"https://www.wowhead.com/achievement=700#comments:id=2606492","https://www.wowhead.com/comment/show-replies?id=2606492","https://www.wowhead.com/achievement=701#comments:id=2320749","https://www.wowhead.com/achievement=701#comments:id=1956270","https://www.wowhead.com/quest=13408/hellfire-fortifications","https://www.wowhead.com/quest=13409/hellfire-fortifications","https://www.wowhead.com/quest=10106#comments:id=163274","https://www.wowhead.com/npc=12795/first-sergeant-holamahi","https://www.wowhead.com/npc=12785/sergeant-major-clate"}, "PvP")
end

for _, money in ipairs({{1176,100},{1177,1000},{1178,5000},{1180,10000},{1181,25000}}) do
    add(money[1], "Got My Mind On My Money", {
        "Track the achievement, then enable automatic looting if desired. This milestone measures cumulative GOLD LOOTED, not how much money is currently in your bags, bank or Warband bank.",
        "Kill creatures and bosses that drop money, then open their loot and take the coins. Combine this with dungeon, raid, quest or reputation runs you already need, and loot ordinary creatures as well as bosses. A shared portion of a party member's coin loot also contributes.",
        "Open reward containers as well as corpses: coins inside a lootable bag count separately from a quest's direct payment. A permanent example is the Bag of Fishing Treasures from Old Man Barlo's Outland fishing daily or Marcia Chase's NORTHREND Dalaran fishing daily. Complete the offered objective, return for the bag, then OPEN it and loot its coins; accepting or handing in the quest alone does not loot the bag's money.",
        "If you already earned I Choose You from the Grand Master Aki pet-tamer quest, check that character's mail for its one-time Heavy Sack of Gold and OPEN the sack. Its 3,000 gold contributes to this series. It is not an endlessly repeatable 3,000-gold daily; starting the full pet-tamer progression solely for a small remaining gold gap is unnecessary.",
        "Continue until the counter reaches " .. money[2] .. " gold. You can spend looted money immediately without losing progress. Selling equipment, receiving mail or trades, Auction House sales and ordinary quest reward money are different income sources and do not replace coin loot.",
    }, {pin(108,38.7,12.8,3,"Old Man Barlo - Outland fishing daily and coin-containing reward bag"),pin(125,52.6,65.6,3,"Marcia Chase - Northrend fishing daily and reward bag")}, "Rogues' pickpocketed coins and money looted from their junkboxes also count. Old advice to recycle almost all of Big Bag of Booty's 300-gold price is unreliable: a 2025 comment and two replies report only about 25-28 gold returned. Previous expansions' raid coin amounts are not promised in Retail.", {"https://www.wowhead.com/achievement=1176#comments:id=656059","https://www.wowhead.com/achievement=1181#comments:id=1534247","https://www.wowhead.com/achievement=1181#comments:id=485004","https://www.wowhead.com/achievement=1181#comments:id=1966536","https://www.wowhead.com/comment/show-replies?id=1966536","https://www.wowhead.com/achievement=7908#comments:id=1769277","https://www.wowhead.com/item=116392#comments:id=6185789","https://www.wowhead.com/comment/show-replies?id=6185789"}, "Other")
end

add(1182, "The Bread Winner", {
    "Track the achievement and inspect Statistics > Character > Wealth > Gold from Quest Rewards if available. This requires 10,000 gold awarded BY QUEST TURN-INS, rather than 10,000 gold looted from enemies.",
    "Complete unfinished story quests and eligible daily quests that list a gold reward. Choose quest lines appropriate to your character's level, finish their objectives and claim the reward from the quest giver.",
    "Continue until the quest-reward counter reaches 10,000 gold. Daily and repeatable quests that actually award money can help; selling a quest's equipment reward to a vendor does not turn the sale into quest-reward gold.",
}, {}, "Do not compare this counter directly with your bank balance or Got My Mind On My Money. Quest rewards and looted coins are counted separately.", {346926,583608,706710,1002832}, "Questing")

add(4496, "It's Over Nine Thousand!", {
    "Open Achievements and check your account's achievement-point total. This milestone asks for more than 9,000 points; there is no currency to spend or NPC to visit.",
    "Open the Incomplete filter and finish short General records you are missing: Can I Keep Him? for one learned pet, Stable Keeper for ten mounts, Represent for one equipped tabard, The Old Gnome and the Sea for a catch from a fish school, or Cooking Award for one award. Use their walkthroughs here; repeating an achievement already earned on the account adds no new points.",
    "Work through unfinished zone discovery lists while doing their story quests. Every completed zone can contribute its exploration record and story record, then feed a regional or Loremaster meta. Check exact missing areas/chapters instead of repeating a finished zone solely for experience.",
    "Run old dungeons and raids for missing completion achievements, then their challenge lists. Read a challenge BEFORE engaging its boss: instantly killing the boss can prevent its required ability, add or timer from occurring and cost a reset. Bring help where a challenge needs several targets or simultaneous actions.",
    "Continue earning distinct achievements until this record awards credit. At exactly 9,000, finish another point-awarding achievement; the stated target is OVER 9,000. If the award appears slightly before the displayed total, no correction is needed: comments and a 2025 reply describe internal totals differing from the displayed faction/account total.",
}, {}, "Completing the same account achievement on another character is not another set of account points. This obtainable record was moved back from Feats of Strength to General; its historical Feat classification does not make it retired. It has no fixed world destination.", {2002071,2332427,3224962,"https://www.wowhead.com/comment/show-replies?id=3224962"}, "Other")

add(941, "Hemet Nesingwary: The Collected Quests", {
    "Enable trivial-quest tracking and check the three component achievements: The Green Hills of Stranglethorn, Hills Like White Elekk and The Snows of Northrend. Complete any branch still missing; visiting Hemet without doing the hunts is insufficient.",
    "At Nesingwary's Expedition in NORTHERN Stranglethorn, take Barnil Stonepot's Welcome to the Jungle. Finish the tiger, panther and raptor hunting chains, then Hemet Nesingwary Jr.'s Big Game Hunter: kill King Bangalash, loot the quest item and turn it in. The obsolete multi-page book collection is not this current hunting requirement.",
    "At Nesingwary Safari in OUTLAND Nagrand, take Clefthoof, Talbuk and Windroc Mastery together. Finish each chain and its named hunt (Banthar, Bach'lor and Gutripper), then complete The Ultimate Bloodsport by killing Tusker, looting the heart and returning to Hemet.",
    "In Sholazar Basin, start at Nesingwary Base Camp: Weslex's engine/parts quests and Debaar's Venture Co. Misadventure -> Wipe That Grin Off His Face. Follow Rhino, Dreadsaber and Crocolisk Mastery. Include Oracle Soo-rahm's offering and Bones of Nozronn when the rhino chain sends you there.",
    "Once those three Sholazar hunts are complete, take In Search of Bigger Game to Dorian Drakestalker. Finish Securing the Bait, Sharpening Your Talons and the follow-ups at his camp, including My Pet Roc, A Mammoth Undertaking and Reagent Agent. Complete Post-partum Aggression and its turn-in, then check all three meta criteria.",
}, {pin(50,44.2,22.2,2,"Barnil Stonepot - Stranglethorn introductions"),pin(50,44,23.4,2,"Hemet Jr. - Big Game Hunter turn-in"),pin(50,47.5,58.5,2,"King Bangalash - final Stranglethorn hunt"),pin(107,71.5,40.7,3,"Nesingwary Safari - three hunting chains"),pin(107,44.4,65.9,3,"Tusker - The Ultimate Bloodsport"),pin(119,25,58,4,"Weslex Quickwrench - engine and parts introduction"),pin(119,27,59,4,"Debaar and Nesingwary Base Camp hunts"),pin(119,25,66,4,"Oracle Soo-rahm - rhino-chain follow-ups"),pin(119,42,28,5,"Dorian Drakestalker - Bigger Game and final hunts")}, "Old comments' kill counts and level-64/75 requirements predate later quest and level changes; use each current quest objective. Turn in the final quests, rather than stopping after a named kill.", {1424501,"https://www.wowhead.com/achievement=938#comments:id=548389","https://www.wowhead.com/achievement=938#comments:id=1044964","https://www.wowhead.com/achievement=940#comments:id=1642180"}, "Questing")

add(1576, "Of Blood and Anguish", {
    "On the character you will use for both chains, travel to the Ring of Blood in OUTLAND Nagrand. Speak to Gurgthock (42.7, 20.7), not an unrelated arena NPC in Draenor's Nagrand.",
    "Complete the six Ring of Blood quests in sequence, returning for each turn-in and accepting the next fight. Finish through The Final Challenge and claim the reward. Stay in the arena so each spawned opponent is part of your active quest.",
    "Travel to the Amphitheater of Anguish in Zul'Drak (48.4, 56.4). Speak to Gurgthock and complete every arena quest offered in the chain, including its elemental encounter and final champion.",
    "Turn in The Champion of Anguish after the final mounted opponent. His mount becomes usable during the fight and can help a character levelling through the area; a high-level character can generally overpower these old encounters. Check both completed quest-chain criteria.",
}, {pin(107,42.7,20.7,1,"Gurgthock - Ring of Blood"),pin(121,48.4,56.4,3,"Gurgthock - Amphitheater of Anguish")}, "The order of the two chains does not matter. A 2023 comment reports they must be completed on the same character, so this route does not depend on combining partial alt progress. The old mandatory five-player group and gold-return estimates are not Retail requirements.", {453458,1509298,5708049}, "Questing")

for _, cook in ipairs({{1795,"Lunch Lady",25},{1796,"Short Order Cook",50},{1797,"Chef de Partie",75},{1798,"Sous Chef",100},{1799,"Chef de Cuisine",160}}) do
    add(cook[1], cook[2], {
        "Use one cook and track the recipe counter. Learn missing recipes from Cooking trainers; train the relevant expansion's Cooking tier when required. Recipes learned on a different character are not recipes learned by this cook.",
        "A large inexpensive trainer batch is Sungshin Ironpaw at Halfhill Market, Valley of the Four Winds (53.5, 51.2). Learn Pandaria Cooking and her missing everyday recipes, including Sliced Peaches, Fish Cake and Yak Cheese Curds. Raise that tier to 5 and return for Rice Pudding. Her current trainer list offers twenty dishes; the Cooking skill itself is not a twenty-first dish. Many use supplies sold at the market rather than rare ingredients.",
        "For recipe scrolls, Alliance can visit Kendor Kabonka upstairs in the Pig and Whistle, Old Town, Stormwind: he sells thirteen low-level recipes, including Westfall Stew, Crocolisk Steak and Gooey Spider Cake. Both factions can use Kelsey Yance in Booty Bay, who sells nine recipes including Giant Clam Scorcho, Cooked Glossy Mightfish, Filet of Redgill and Hot Smoked Bass. Buy only unlearned scrolls your cook can use, then right-click to LEARN each one; purchasing a finished food is different.",
        "In Shattrath's World's End Tavern, train Outland Cooking from Kylene and return as its skill increases. Her three dishes are Stewed Trout, Fisherman's Feast and Hot Buttered Trout; the latter two require Outland Cooking 75. Other Outland food/fishing vendors supply more scrolls. This preserves the useful older-vendor route without depending on removed original-world quests.",
        "In NORTHREND Dalaran, learn unlearned trainer recipes and buy missing recipes from Derek Odds beside Katherine Lee for Alliance, or Misensi beside Awilo Lon'gomba for Horde. These suppliers use Epicurean's Awards. Do their cooking dailies and the capital-city daily to earn awards; see Cooking Award for the repeatable Waterlogged Recipe alternative. Open the recipe's Unlearned entry to see its tier, required skill and source.",
        "If only a few recipes remain, search the Auction House's Cooking recipes for inexpensive unlearned scrolls before waiting through many daily resets. Compare the scroll's name and required Cooking tier with this character's known recipes. Optional holiday recipes also count when their events are active; waiting for a holiday is unnecessary when a permanent unlearned recipe is available.",
        "Continue learning distinct recipes on this character until the counter reaches " .. cook[3] .. ". Cooking the same dish repeatedly raises skill when eligible, but does not add another learned recipe. You do not need a removed recipe, every recipe in the game, or every faction-exclusive recipe to reach this target.",
    }, {pin(376,53.5,51.2,2,"Sungshin Ironpaw - twenty Pandaria everyday recipes"),pin(84,76.6,53,3,"Kendor Kabonka - thirteen scrolls; upstairs Pig and Whistle"),pin(210,42.8,69,3,"Kelsey Yance - nine neutral recipe scrolls"),pin(111,75,32.6,4,"Kylene - three Outland recipes, World's End Tavern"),pin(125,40.4,65.8,5,"Derek Odds and Katherine Lee - Alliance Northrend recipes"),pin(125,70,38.6,5,"Misensi and Awilo Lon'gomba - Horde Northrend recipes")}, "Stop as soon as your target credits. Older comments claiming you need Thistle Tea, Dirge's Kickin' Chimaerok Chops or every seasonal recipe predate the larger recipe pool. If newly learned recipes appear absent from the counter, relog once and learn another genuinely missing recipe rather than buying duplicates.", {"https://www.wowhead.com/achievement=1798#comments:id=428820","https://www.wowhead.com/comment/show-replies?id=428820","https://www.wowhead.com/achievement=1799#comments:id=952463","https://www.wowhead.com/achievement=1799#comments:id=1884755","https://www.wowhead.com/comment/show-replies?id=1884755","https://www.wowhead.com/npc=64231/sungshin-ironpaw","https://www.wowhead.com/npc=2664/kelsey-yance","https://www.wowhead.com/npc=19186/kylene"}, "Professions")
end

for _, award in ipairs({{1998,1},{1999,10},{2000,25},{2001,50},{2002,100}}) do
    add(award[1], award[2] == 1 and "Cooking Award" or award[2] .. " Cooking Awards", {
        "Learn Cooking and visit your faction's cooking daily quest giver in NORTHREND Dalaran: Katherine Lee at 40.3, 66.1 for Alliance, or Awilo Lon'gomba at 70.0, 38.9 for Horde. Train the required Cooking tier/skill if the offered quest is unavailable for lack of skill.",
        "Accept TODAY'S offered daily, collect or cook exactly what it requests and turn it in. Only one of this Dalaran rotation is available per day; you cannot complete all five variants each day. Mustard Dogs! awards two rather than one. Claim the awards, open the Small Spice Bag and inspect the achievement counter.",
        "Add one capital-city cooking daily on the SAME character that day: Robby Flay in Stormwind (50.6, 71.6) or Marogg in Orgrimmar (56.6, 62.6). The capital-city rotation is separate from Northrend Dalaran's. Switching between your faction's three capital quest givers does not provide three capital dailies; inspect their offered rewards before choosing if you want the two-award variant.",
        "For a supplement, do Marcia Chase's Northrend fishing daily and open its Bag of Fishing Treasures. If it contains Waterlogged Recipe, right-click the quest-starting item and deliver it to Christi Stockton in One More Glass (53.4, 33.2, NORTHREND Dalaran) for five Epicurean's Awards. Learn Northrend Cooking first. The current unbound quest item can also be bought from the Auction House; compare its price before buying several.",
        "Waterlogged Recipe is repeatable: complete its hand-in before accepting the next copy. Check the counter after the first one. Otherwise return for the cooking dailies after each daily reset until you have earned " .. award[2] .. " awards. The target counts awards earned, so a two-award daily or five-award recipe can advance it by more than one.",
        "Spend earned awards on needed recipes if desired; the achievement tracks accumulation rather than requiring all awards in your wallet at once. Save enough for a Chef's Hat separately if you want that purchase.",
    }, {pin(125,40.3,66.1,1,"Katherine Lee - Alliance cooking daily"),pin(125,70,38.9,1,"Awilo Lon'gomba - Horde cooking daily"),pin(84,50.6,71.6,3,"Robby Flay - additional Alliance capital daily"),pin(85,56.6,62.6,3,"Marogg - additional Horde capital daily"),pin(125,52.6,65.6,4,"Marcia Chase - fishing daily; check reward bag"),pin(125,53.4,33.2,4,"Christi Stockton - five-award Waterlogged Recipe hand-in"),pin(125,53.4,33.2,5,"Christi Stockton - repeat with further recipe copies")}, "The currency is now named Epicurean's Award. October-November 2010 comments saying these achievements were disabled describe the old currency transition; later comments confirm credit was restored. Waterlogged Recipe needs Northrend Cooking 1 in current Retail, not the old unified 350 Cooking. Relog once if a completed hand-in fails to refresh the display.", {"https://www.wowhead.com/achievement=1999#comments:id=454853","https://www.wowhead.com/achievement=2001#comments:id=1173409","https://www.wowhead.com/achievement=2001#comments:id=1672520","https://www.wowhead.com/achievement=2002#comments:id=1182501","https://www.wowhead.com/item=49667/waterlogged-recipe","https://www.wowhead.com/quest=14203/waterlogged-recipe","https://www.wowhead.com/npc=32337/christi-stockton","https://us.forums.blizzard.com/en/wow/t/epicurean-currency/2223818"}, "Professions")
end

add(1563, "Hail to the Chef", {
    "Choose a cook and expand the meta's missing achievements. Learn Northrend Cooking in Northrend Dalaran and raise that tier to 75 for Northrend Cook. Learn 100 distinct cooking recipes for Sous Chef; reaching 75 in a different expansion's tier is not the same criterion.",
    "Start The Rokk's Shattrath cooking daily early. Complete all four variants as they rotate: Manalicious, Revenge is Tasty, Soup for the Soul and Super Hot Stew. Open each Barrel of Fish/Crate of Meat and learn missing recipes, particularly Stormchops, Kibler's Bits, Skullfish Soup, Spicy Hot Talbuk and Delicious Chocolate Cake. The random recipes can take longer than the four quest variants.",
    "Also complete the five NORTHREND Dalaran cooking daily variants for Our Daily Bread: Cheese for Glowergold, Convention at the Legerdemain, Infused Mushroom Meatloaf, Mustard Dogs! and Sewer Stew. Katherine Lee serves Alliance; Awilo Lon'gomba serves Horde. Only today's variant is offered. Open the Small Spice Bag and save Epicurean's Awards for the recipe supplier beside your trainer.",
    "Complete The Outland Gourmet and The Northrend Gourmet's 45-recipe tier by COOKING every missing listed dish. Kylene in Shattrath directly teaches the three easy-to-miss recipes Stewed Trout, Fisherman's Feast and Hot Buttered Trout. Northrend's supplier sells Fish Feast, Worg Tartare and other recipes for awards. Gather each dish's ingredients; learning a recipe, buying its finished food or eating it does not replace cooking it.",
    "For the Kungaloosh gap in Northrend Gourmet, finish Grimbooze Thunderbrew's brewing quests at Nesingwary Base Camp, Sholazar Basin, including The Taste Test. Then speak to the Washed-Up Mage in the NORTHREND Dalaran Underbelly to learn Kungaloosh, and brew it. Use the Underbelly map entry for the mage; this is not Legion Dalaran's sewer.",
    "For The Cake Is Not A Lie, learn the random Delicious Chocolate Cake recipe and BAKE the cake. For Captain Rumsey's Lager, learn its recipe from an Outland/Northrend fishing daily's treasure bag, then BREW the lager. Buying either finished drink/cake is insufficient. Keep doing The Rokk and Dalaran dailies while waiting on recipe drops; Timewalking recipe containers provide extra chances when their event vendors are active.",
    "For Second That Emotion, EAT Bad Clams, Haunted Herring, Last Week's Mammoth and Tasty Cupcake. These four are eating criteria, unlike the Gourmet dishes. They can be bought as finished food if you do not want to cook them yourself; check each tick after consuming it.",
    "For Critter Gitter, bring at least ten Critter Bites to the Glacier Penguins northwest of Icecrown's Argent Tournament grounds, around 66.0, 21.7. Put the bites on an action bar and use one on each of ten DIFFERENT nearby penguins within three minutes. They stand close together. Avoid attacks/area damage that kill them. A February 2026 reply confirms this location; northern Mulgore's critter mesa around 35, 8 is another reported option.",
    "For Dinner Impossible, bring at least four GREAT FEASTS and place one during a match on each required map: Alterac Valley, Warsong Gulch, Arathi Basin and Eye of the Storm. Use the queue appropriate to the map; Alterac Valley is an epic battleground. Check each map's tick after placing it. A Fish Feast is not the specified item, and merely carrying feasts into a match is insufficient.",
    "Return to the meta, finish any remaining unchecked component and select the Chef title. Keep the recipe learning/cooking work on this cook. The title needs Sous Chef's 100 recipes, not Chef de Cuisine's 160 recipes, and owning a Chef's Hat is not a meta requirement.",
}, {pin(125,40.3,66.1,1,"Katherine Lee - Alliance Northrend Cooking"),pin(125,70,38.9,1,"Awilo Lon'gomba - Horde Northrend Cooking"),pin(111,61.6,15.6,2,"The Rokk - four rotating Outland cooking dailies"),pin(125,40.3,66.1,3,"Katherine Lee - five Alliance daily variants"),pin(125,70,38.9,3,"Awilo Lon'gomba - five Horde daily variants"),pin(111,75,32.6,4,"Kylene - three Outland Gourmet recipes"),pin(125,40.4,65.8,4,"Derek Odds - Alliance award recipes"),pin(125,70,38.6,4,"Misensi - Horde award recipes"),pin(119,26.8,60,5,"Grimbooze Thunderbrew - brewing chain through The Taste Test"),pin(126,43.4,24.6,5,"Washed-Up Mage - learn Kungaloosh","Dalaran Underbelly (Northrend)"),pin(108,38.7,12.8,6,"Old Man Barlo - fishing bag chance for Lager recipe"),pin(125,52.6,65.6,6,"Marcia Chase - Northrend fishing bag chance for Lager recipe"),pin(118,65.95,21.69,8,"Glacier Penguins - ten Critter Bites within three minutes"),pin(7,35,8,8,"Northern critter mesa - alternative Critter Gitter group")}, "The old 450 unified Cooking cap has been replaced by expansion tiers. The Northrend Gourmet requirement is the 45-dish tier; a 2011 comment describing its 30-dish tier is outdated. Complete each dish's actual learn/cook/eat/place requirement rather than treating those actions as interchangeable.", {369975,628439,1822824,2304647,"https://www.wowhead.com/achievement=1799#comments:id=952463","https://www.wowhead.com/achievement=1781#comments:id=1932522","https://www.wowhead.com/comment/show-replies?id=1932522","https://www.wowhead.com/achievement=1781#comments:id=6202649","https://www.wowhead.com/npc=32516/washed-up-mage","https://www.wowhead.com/achievement=125/northrend-cook"}, "Professions")

add(1516, "Accomplished Angler", {
    "Expand the meta and start its daily/random parts early. Learn Fishing and Find Fish; Angler's Guide teaches the tracking ability (see Fish Don't Leave Footprints). Visit Old Man Barlo beside Silmyr Lake, Terokkar Forest, after each daily reset. Complete all five variants for Old Man Barlowned: Bait Bandits, Crocolisks in the City, Felblood Fillet, Shrimpin' Ain't Easy and The One That Got Away. Only the offered variant is available that day.",
    "Start Mr. Pinchy while waiting for those daily rotations. Fly between Terokkar's elevated Blackwind Lake, Lake Ere'Noru and Lake Jorune, fishing INSIDE Highland Mixed Schools. When you catch Mr. Pinchy, use his wishes as their cooldown permits. You specifically need a wish that grants Magical Crawdad Box, then learn its pet; a different wish or merely catching Mr. Pinchy does not finish the criterion. Fish another Mr. Pinchy if all three wishes fail.",
    "Prepare for Stranglethorn Fishing Extravaganza using the CURRENT in-game calendar. Before it starts, set your Hearthstone at Booty Bay's inn, make sure it is ready, enable Find Fish/Auto Loot and bring water walking if useful. Scout a short circuit of ordinary fishing nodes in Northern Stranglethorn or the Cape; the coast south of Grom'gol and the west coast near Booty Bay are reported options. Start at the advertised event time, not an old comment's unconverted time zone.",
    "While the event's world quest is active, fish INSIDE ordinary fish schools or wreckage pools in Stranglethorn for 40 Speckled Tastyfish. Do not wait for a separate School of Tastyfish: that older pool type was removed. Move to the next nearby node when one is empty. At 40, hearth to Booty Bay and immediately hand them to Riggle Bassbait for Master Angler of Azeroth. Winning places are limited; having 40 fish alone is insufficient. If a chat announcement says it is over, still check Riggle while your own quest remains active, since a 2026 comment reports announcements from other realms.",
    "Learn NORTHREND Fishing from Marcia Chase and raise that tier to 75 for Northrend Fisherman. Complete Outland Angler and Northrend Angler by fishing every school type on their checklists. Keep the bobber inside each pool and loot the catch. This also builds 1000 Fish; do not grind a thousand separate casts before starting the named-school achievements.",
    "Fish the five wreckage types for The Scavenger and one qualifying school for The Old Gnome and the Sea, using their mapped routes here. For One That Didn't Get Away, follow the separate rare-fish walkthrough: scenario Andorhal or Stonebull Lake are alternatives. Small ordinary mud snappers/catfish are not the qualifying heavy fish.",
    "For The Coin Master, fish the fountain beside the bank in NORTHREND Dalaran until its Copper, Silver and Gold coin checklists are complete. Use caught Dalaran Gold Coins to refresh the coin-catching buff. Keep checking the missing names; duplicate coins do not replace the last missing one. Legion Dalaran has a different coin collection.",
    "For The Fishing Diplomat, make an actual catch in both Stormwind and Orgrimmar. The mapped canals/Valley of Honor water are examples. In the enemy city, find a quiet casting position away from guards and players before fishing; entering the city or dying there does not award fishing credit.",
    "For The Lurker Above, enter the ORIGINAL Serpentshrine Cavern through Coilfang Reservoir. Reach the Strange Pool in the centre of the raid, stand on its surrounding walkway and cast into the pool until The Lurker Below is summoned. This is a summon achievement, so killing the entire raid is unnecessary. Recheck the parent checklist and select the Salty title once all components credit.",
}, {pin(2393,44.98,59.69,1,"Olirea - Angler's Guide for Find Fish"),pin(108,38.7,12.8,1,"Old Man Barlo - check today's variant each reset"),pin(108,64.5,76,2,"Blackwind Lake - Highland Mixed School circuit"),pin(108,59,40,2,"Lake Ere'Noru - elevated school search"),pin(108,45,40.5,2,"Lake Jorune - elevated school search"),pin(210,27.4,77.2,3,"Booty Bay inn - set Hearthstone before the event"),pin(50,43,58,3,"Bay south of Grom'gol - optional node circuit"),pin(50,43,58,4,"Fish active Stranglethorn nodes during the world quest"),pin(210,27.4,76.8,4,"Riggle Bassbait - turn in 40 fish before winning places run out"),pin(125,52.6,65.6,5,"Marcia Chase - learn Northrend Fishing"),pin(7,44.3,61.1,6,"Stonebull Lake - alternative rare-fish route"),pin(125,52.6,67,7,"Northrend Dalaran fountain - three coin collections"),pin(84,55,69,8,"Stormwind canals - actual catch required"),pin(85,69,30,8,"Orgrimmar Valley of Honor water - actual catch required"),pin(102,50.2,41,9,"Coilfang Reservoir - enter original Serpentshrine Cavern")}, "A September 2026 comment confirms the Salty meta remains obtainable. The original Zul'Gurub Gahz'ranka summon and the retired Kalu'ak Fishing Derby are not required routes. Perception and expensive gear do not guarantee rare drops or a tournament win. Choose War Mode before travelling if desired; a quieter shard is only a possibility and exposes you to player attacks.", {1034437,5331890,6058553,6409720,"https://www.wowhead.com/achievement=306#comments:id=5755234","https://www.wowhead.com/achievement=306#comments:id=6408796","https://www.wowhead.com/quest=44765/stranglethorn-fishing-extravaganza","https://www.wowhead.com/achievement=130/northrend-fisherman","https://www.wowhead.com/achievement=1243#comments:id=6129610"}, "Professions")

add(46, "Universal Explorer", {
    "Expand this meta and its nine regional Explorer achievements. Each regional meta opens zone achievements, and each zone opens its named discovery areas. Track the lowest incomplete checklist; simply uncovering most of a continent is insufficient.",
    "Complete Eastern Kingdoms and Kalimdor zone discovery lists, then Outland and Northrend. Fly or ride into each missing named area and wait for its discovery credit before moving on; descend if passing high overhead does not count. A fully revealed-looking map can still have an undiscovered small reef or settlement, particularly on Bloodmyst Isle. Use the zone achievement's checklist to find the remaining name. You generally need to discover an enemy city, not fight its leader.",
    "For destroyed or rebuilt areas, use the accessible Retail past phase where required: Zidormi at Darkshore 48.8, 24.5 for Teldrassil/Darnassus, at Tirisfal Glades 69.5, 62.8 for old Undercity, and beside the old Ghostlands portal at Eastern Plaguelands 53.8, 8.6 for Burning Crusade Eversong/Ghostlands. A similarly named Midnight zone does not replace the old map's discoveries. The old blood-elf and draenei starting maps restrict flight, so finish their missing areas on the ground.",
    "Complete Cataclysm Explorer's separate zone lists, including Hyjal, Deepholm, Vashj'ir, Uldum and Twilight Highlands. These are not all covered by the original Kalimdor/Eastern Kingdoms regional metas.",
    "Finish Pandaria, Draenor and Broken Isles discovery metas. In Draenor and Outland, keep their two versions of Nagrand and Shadowmoon Valley separate; discovering one does not discover the other.",
    "Finish Battle for Azeroth Explorer across BOTH Kul Tiras and Zandalar. Check the parent meta again and clear any remaining regional/zone entries to earn the Explorer title. Its present list ends at BfA; unrelated later-expansion exploration is not a substitute for a missing listed region.",
}, {pin(62,48.8,24.5,3,"Zidormi - old Darkshore and Teldrassil"),pin(18,69.5,62.8,3,"Zidormi - pre-battle Tirisfal and Undercity"),pin(23,53.8,8.6,3,"Zidormi and old Ghostlands portal - Burning Crusade Quel'Thalas")}, "The map selector offers the required regions plus the phase-switch locations. Phase pins do not mark completion of a whole continent. Use the individual zone guides for named discovery locations. Map-revealing addons can hide the visual distinction between discovered and missing areas; the achievement checklist is the useful check. The Explorer title does not require rare-spawn killing achievements.", {337000,339562,383431,1394354,"https://www.wowhead.com/comment/show-replies?id=337000","https://www.wowhead.com/npc=259326/zidormi","https://www.wowhead.com/guide/transportation"}, "Exploration")
guides[46].areaMaps = {13,12,101,113,198,207,203,249,241,424,572,619,876,875}

add(964, "Going Down?", {
    "Reach Valdrakken and heal to full. Go to the raised platform in the Sapphire Enclave near the Relaxing Dragon at 38.0, 28.0. Check the lower landing area before stepping off.",
    "Walk straight off the platform in the direction the dragon faces and fall to the lower city without dying. The required drop is 65 yards; a small jump from a low wall is not enough.",
    "Check the achievement after landing. You only need one surviving fall. If using another location, choose a known survivable drop or a fall-protection ability; do not assume any flight high above the city will be survivable.",
}, {pin(2112,38,28,1,"Sapphire Enclave platform - Relaxing Dragon")}, "Begin at full health and use the specified platform and direction. A fall well beyond the required 65 yards can still be fatal. This route needs neither alcohol nor Brewfest.", {5692093,"https://www.wowhead.com/npc=187640/relaxing-dragon"}, "Exploration")

add(1206, "To All The Squirrels I've Loved Before", {
    "Track the 21-species checklist. LEFT-click a critter to target it, then type /love with nothing after it. The message should name the target; 'You feel the love' means you had no valid target. Do not right-click and accidentally kill it. A corpse can still receive /love if it remains targetable.",
    "Save travel with captured pets: summon, target and /love a matching Cat, Chicken, Fawn, Small Frog, Hare, Parrot, Rabbit, Shore Crab, Skunk, Squirrel, Toad or Prairie Dog already in your Pet Journal. A friend can summon them too. Check each tick rather than assuming every similarly named pet qualifies. If visiting Stormwind, Audrey Burnhep's cages near 69.2, 25.0 provide Squirrel, Rabbit and Prairie Dog; its Mage Quarter grass also has Squirrels.",
    "In Elwynn Forest, search the house by the Northshire road around 44.4, 52.4 for Cat. A 2024 reply warns that the cats on TOP of the building may fail: use one on the GROUND. Around 32.4, 53.6, /love Fawn beside Deer; Rabbit also appears around 34, 54. Check these separately even when they roam together.",
    "Continue through Goldshire: Chicken outside the inn around 42.5, 66.2, Cow near 41.8, 69.4 and Sheep near 42.0, 70.0. Search Crystal Lake's western bank around 45.2, 66.8 for Small Frog. These fill the remaining common Elwynn criteria; repeating a species you already loved adds nothing.",
    "In Duskwood, look around Raven Hill's graveyard for Skunk. In Loch Modan, /love a Ram near the western approaches. Skip a completed species rather than repeating every stop in the route.",
    "In Durotar, /love Swine in Tor'kren Farm's pen around 43.6, 30.3, Toad by the watershed and Hare around Drygulch Ravine/coast. A boar enemy is not the named Swine critter.",
    "In Northern Barrens, find Gazelle north of Crossroads or near the Forgotten Pools. For Prairie Dog, check the surrounding plains and roads if you did not finish it with a pet or Audrey's cage.",
    "In Un'Goro Crater, /love a Parrot. This is the ordinary critter or matching captured Parrot, not an arbitrary colourful parrot companion. The mapped point is a search area; scan nearby roaming critters.",
    "In Shattrath's Lower City, /love Ewe underneath the northern bridge around 59, 22. An ordinary Sheep does not replace this separate criterion.",
    "Finish in Borean Tundra: Borean Frog in the Geyser Fields, Steam Frog north of Taunka'le Village, and Shore Crab by the cave on Coldarra's northeastern coast. This route uses Shore Crab, not the unrelated Strand Crab from old bug comments.",
    "Check all 21 ticks before leaving the last zone. If the checklist appears complete without the achievement, recheck the actual targets used for your last species. Capturing a pet, typing /love without targeting it or emoting while riding a flight-path taxi does not replace the targeted emote.",
}, {pin(84,69.2,25,2,"Audrey Burnhep's cages - Squirrel, Rabbit and Prairie Dog"),pin(84,44.2,79.8,2,"Mage Quarter grass - alternative Squirrel"),pin(37,44.4,52.4,3,"Northshire road house - use a Cat on the GROUND"),pin(37,32.4,53.6,3,"Deer and Fawn - target each species"),pin(37,34,54,3,"Rabbit search area"),pin(37,42.5,66.2,4,"Goldshire inn - Chicken"),pin(37,41.8,69.4,4,"South of Goldshire - Cow"),pin(37,42,70,4,"South of Goldshire - Sheep"),pin(37,45.2,66.8,4,"Crystal Lake western bank - Small Frog"),pin(47,21,46,5,"Raven Hill graveyard - Skunk"),pin(48,21,72.4,5,"Loch Modan western approach - Ram"),pin(1,43.63,30.34,6,"Tor'kren Farm - Swine"),pin(1,34.8,43.4,6,"Watershed - Toad"),pin(1,40.8,17.6,6,"Northern Durotar - Hare"),pin(10,36,43.6,7,"Forgotten Pools region - Gazelle and Prairie Dog search"),pin(78,26,45,8,"Un'Goro - Parrot search area"),pin(111,59,22,9,"Lower City northern bridge - Ewe"),pin(114,69.2,29,10,"Geyser Fields - Borean Frog"),pin(114,77.4,31.8,10,"North of Taunka'le - Steam Frog"),pin(114,37.8,23,10,"Coldarra coast cave - Shore Crab")}, "Moving critters are search-area pins, not guaranteed stationary spawns. Old lists call Small Frog 'Frog' and Shore Crab 'Crab'. Only twelve of these species have the matching captured-pet shortcut; Borean Frog, Steam Frog, Cow, Deer, Ewe, Gazelle, Ram, Sheep and Swine still need their world targets.", {406417,1638557,1859103,1999154,3165714,3300581,6254876,"https://www.wowhead.com/comment/show-replies?id=1638557","https://www.wowhead.com/comment/show-replies?id=1859103","https://www.wowhead.com/comment/show-replies?id=1999154","https://www.wowhead.com/comment/show-replies?id=3165714","https://www.wowhead.com/npc=63596/audrey-burnhep","https://www.wowhead.com/npc=6368/cat","https://www.wowhead.com/npc=25677/borean-frog","https://www.wowhead.com/npc=25679/steam-frog"}, "Exploration")

add(2556, "Pest Control", {
    "Track the pest checklist and use ordinary damaging attacks on the named world critters. This achievement requires KILLS; /love, collecting a pet or defeating a different enemy with a similar name is not the stated action.",
    "Start in NORTHREND Dalaran and descend into the Underbelly for Underbelly Rat. In Howling Fjord, enter Utgarde Catacombs at the mapped point and descend to the LOWER pit with ghouls for Devouring Maggot; this is underground, not inside the Utgarde Keep dungeon. Kill Fjord Rat around Wyrmskull/Valgarde and the ordinary Maggot around Halgrind. These two maggots are separate criteria. In Zul'Drak, find Zul'Drak Rat near the Amphitheater. For an optional Mouse shortcut en route, wait for the roaming deer/fawn/mouse pack around Grizzly Hills 19, 74; otherwise use Westfall in the last step.",
    "In Winterspring, kill Crystal Spider around Lake Kel'Theril. In Durotar, find Adder and Water Snake around the inland waters. In Ashenvale, find Roach; leave the ordinary Snake criterion for the mapped Westfall stop. Wild-pet versions can be targeted in the world as well.",
    "In Eastern Plaguelands' western area, kill Scorpid (the old Scorpion criterion) and Spider. For Larva, use the still-accessible Burning Crusade Ghostlands: switch with Zidormi at the southern Quel'Thalas gate before travelling there. Look around the old western Dead Scar/ruins, not Midnight's Eversong coordinates.",
    "In Badlands, find Gold Beetle in the northern zone. In Burning Steppes' northwest, find Fire Beetle. These outdoor options avoid entering a dungeon just for either pest.",
    "In Stormwind, finish Squirrel and Rat. In Westfall, finish Mouse and the ordinary Snake. Check the remaining checklist for any uncredited species; these are separate from Underbelly Rat, Fjord Rat and Zul'Drak Rat. If every visible box looks complete but the achievement is missing, recheck recently killed Crystal Spider and Water Snake, which comments identify as past display problems.",
}, {pin(125,60,47.5,2,"Descend to Northrend Dalaran's Underbelly - Rat"),pin(117,56.8,54,2,"Utgarde Catacombs - Devouring Maggot in the LOWER pit"),pin(117,59.2,50,2,"Wyrmskull/Valgarde - Fjord Rat search"),pin(117,49.6,54.2,2,"Halgrind - ordinary Maggot"),pin(116,19,74,2,"Roaming deer/fawn/mouse pack - optional Mouse shortcut"),pin(121,40.8,62.6,2,"Amphitheater region - Zul'Drak Rat"),pin(83,48,54.8,3,"Lake Kel'Theril - Crystal Spider"),pin(1,36.4,25.6,3,"Durotar - Adder"),pin(1,35,44.8,3,"Watershed - Water Snake"),pin(63,38.8,30.6,3,"Ashenvale - Roach search"),pin(23,4.6,35.6,4,"Western Eastern Plaguelands - Scorpid"),pin(23,4.4,35.8,4,"Western Eastern Plaguelands - Spider"),pin(23,53.8,8.6,4,"Zidormi and old Ghostlands portal - reach the Larva map"),pin(95,20.6,52.6,4,"Burning Crusade Ghostlands - Larva","Ghostlands (Burning Crusade)"),pin(15,41.8,10.6,5,"Northern Badlands - Gold Beetle"),pin(36,16.8,21.8,5,"Northwestern Burning Steppes - Fire Beetle"),pin(84,44.2,79.8,6,"Stormwind grass - Squirrel"),pin(84,60.4,68.8,6,"Stormwind canal - Rat"),pin(52,29.2,45,6,"Westfall - Mouse search if still missing"),pin(52,32.2,48.2,6,"Westfall - Snake search")}, "Use /targetexact followed by the missing critter's name if it is hard to click, then mark it with a raid target icon to locate it. The old Moccasin is now Water Snake and Scorpion is displayed as Scorpid. Maggot does not substitute for Devouring Maggot. Roaming critter markers identify search areas; the Grizzly Hills pack moves past its pin.", {572897,574277,3177713,3149353,5282826,"https://www.wowhead.com/comment/show-replies?id=572897","https://www.wowhead.com/comment/show-replies?id=574277","https://www.wowhead.com/comment/show-replies?id=1712449","https://www.wowhead.com/npc=16068/larva","https://www.wowhead.com/npc=32258/gold-beetle","https://www.wowhead.com/npc=32261/crystal-spider","https://www.wowhead.com/npc=259326/zidormi"}, "Exploration")

add(603, "Wrath of the Horde", {
    "On a Horde character, track all four city criteria: Stormwind, Ironforge, Darnassus and Exodar. You need five Alliance player kills credited in EACH city, not five total and not the city leaders.",
    "Find a willing opposite-faction partner or enemy players in the city. Both characters must be able to see and attack one another in the same phase/PvP setting. Position inside the named city's boundary before the kill; a nearby starting zone is not the city criterion.",
    "Complete five kills in Stormwind and five in Ironforge. A quiet interior and a partner who can resurrect can reduce guard interruptions. Recheck each city after its fifth kill rather than assuming a single visible check proves the whole achievement.",
    "For Darnassus, visit Zidormi in Darkshore (48.8, 24.5) and select the past before the burning. Both characters must use the same phase. Enter Darnassus and finish its five kills; proceed through Rut'theran's Azuremyst connection to reach Exodar for its five kills.",
    "Verify all four counters. Comments confirm low-level players and repeated kills of the same player can count, so this is not an honorable-kill requirement. Use a partner rather than depending on the old rapid Alt-F4 character-switch trick.",
}, {pin(84,71,95,3,"Stormwind entrance tower - verify city boundary"),pin(87,25,11,3,"Ironforge outer neighbourhood - arrange a safe interior"),pin(62,48.8,24.5,4,"Zidormi - return Darkshore to the past"),pin(89,43,32,4,"Darnassus - city kill search area"),pin(103,50,50,4,"Exodar - city kill search area")}, "Darnassus remains accessible through Retail's past phase. The 2025 comment explicitly calls out this phase switch; older obsolete boat instructions are replaced. War Mode is not the only PvP flag, but participants must use compatible settings and phases.", {1579426,5466704,6043220,"https://www.wowhead.com/npc=141489/zidormi"}, "PvP")

add(604, "Wrath of the Alliance", {
    "On an Alliance character, track the four criteria: Orgrimmar, Thunder Bluff, Undercity and Silvermoon City. Each requires five Horde player kills; neither guards nor faction leaders replace player kills.",
    "Use player targets in the city or arrange a willing opposite-faction partner in the same phase and PvP setting. Check that the game identifies both locations as the named city before starting. A low-level partner can count, and the same partner can return after resurrection.",
    "Complete five kills in Orgrimmar, then Thunder Bluff. For Thunder Bluff, the ground beneath the rises can still register as the city, avoiding the busiest platforms. Check the criterion after five kills at your chosen spot.",
    "For Undercity, both characters use Zidormi in Tirisfal Glades (69.5, 62.8) to return to the pre-destruction phase. Enter the city and complete its five kills; the plague-covered present-day ruins are not substituted for the old city interior.",
    "For Silvermoon, use Zidormi/the old-zone portal at the southern Quel'Thalas gate to enter the BURNING CRUSADE version still available in Retail. Move both characters to that version of Silvermoon and finish five kills there. Do not use Midnight city coordinates on the old map.",
}, {pin(85,56.94,93.27,3,"Orgrimmar front-wall edge - verify city boundary"),pin(88,60,34,3,"Ground beneath Thunder Bluff rises - city boundary"),pin(18,69.5,62.8,4,"Zidormi - old Undercity phase"),pin(90,65,47,4,"Undercity - interior kill search area"),pin(23,53.8,8.6,5,"Zidormi - enter Burning Crusade Quel'Thalas"),pin(110,81,58,5,"Old Silvermoon - Wayfarer's Rest area","Silvermoon City (Burning Crusade)")}, "The original four-city criteria are retained with current Retail phase access. The guide does not rely on the old disconnect exploit or on obsolete claims that a kill must award Honor.", {1348763,1890219,2261398,6334245,"https://www.wowhead.com/npc=141488/zidormi","https://www.wowhead.com/npc=259326/zidormi","https://www.wowhead.com/guide/transportation"}, "PvP")

add(614, "For the Alliance!", {
    "On an Alliance character, inspect the CURRENT meta: Killed in Quel'Thalas and Opposing Orgrimmar. Form a group with a tank and healing support; a current-season leader's health and player defenders can make the old solo claims misleading.",
    "Reach Burning Crusade Silvermoon through Zidormi/the portal at Quel'Thalas's southern gate. Enter Sunfury Spire and find the attackable Lor'themar Theron at the old throne position, around 54.0, 20.6 on the OLD Silvermoon map. This is not a friendly quest copy in Midnight Silvermoon.",
    "Bring the group together before pulling Lor'themar and his nearby guards/advisers. Keep everyone in range for credit, deal with adds and kill the correct leader. Check Killed in Quel'Thalas before travelling on.",
    "In Orgrimmar, enter Grommash Hold in the Valley of Strength and kill Rokhan for Opposing Orgrimmar. Keep the tank supported, handle defending players and avoid pulling the leader out far enough to reset. If the room contains an old warchief instead, leave an incompatible quest phase or use a character in the current phase.",
    "Verify both meta criteria and check the Mount Journal/reward mail for the Black War Bear. The older four-capital route through Sylvanas, Baine and an old warchief is not the current meta's checklist.",
}, {pin(23,53.8,8.6,2,"Zidormi - enter Burning Crusade Quel'Thalas"),pin(110,54,20.6,2,"Lor'themar Theron - old Sunfury Spire","Silvermoon City (Burning Crusade)"),pin(85,48.4,70.6,4,"Grommash Hold - Rokhan")}, "Current criteria were read on both the meta and its two component pages. July 2026 comments confirm Rokhan remains attackable in Midnight. The past Quel'Thalas route remains available in Retail; it does not require playing a Classic client.", {"https://www.wowhead.com/achievement=613/killed-in-quelthalas","https://www.wowhead.com/achievement=14817#comments:id=6384089","https://www.wowhead.com/npc=16802/lorthemar-theron","https://www.wowhead.com/npc=259326/zidormi","https://www.wowhead.com/guide/transportation"}, "PvP")

add(619, "For the Horde!", {
    "On a Horde character, inspect the CURRENT meta: Overthrow the Council and Putting Out the Light. Form a group with a tank, healer and damage dealers; old raid-size and item-level estimates are not current requirements.",
    "Enter Ironforge and gather near the High Seat before pulling. A warlock with helpers can set up a summon away from the busiest approach, as the numbered comment suggests. Bring everyone into the room together instead of fighting guards separately along the route.",
    "Kill Moira Thaurissan, Muradin Bronzebeard and Falstad Wildhammer for Overthrow the Council. Prioritize Moira's healing, interrupt where possible and keep your back to a wall against Muradin's knockbacks. Avoid being pushed out of the room and resetting the encounter.",
    "Travel to Exodar and the Vault of Lights. Kill Prophet Velen, clearing his Vigilant Defenders and moving him out of his yellow healing pool. Keep within his encounter area so movement does not reset him; deal with respawned defenders if they make him immune.",
    "Check both meta criteria and the Black War Bear reward. Killing Stormwind's current leader or visiting destroyed Darnassus is not required by the present two-component meta.",
}, {pin(87,39.6,56.4,2,"High Seat - gather before Council pull"),pin(87,39.6,56.4,3,"Council - Moira, Muradin and Falstad"),pin(103,32.6,54.6,4,"Vault of Lights - Prophet Velen"),pin(103,31.3,47.9,4,"Vault of Lights wall - knockback positioning")}, "The Council criterion requires all three named leaders, not old Magni. Clear Velen's defenders again if they respawn and make him immune. Enemy players can interrupt these attacks, so keep the group together.", {"https://www.wowhead.com/achievement=616#comments:id=744256","https://www.wowhead.com/achievement=616#comments:id=6226326","https://www.wowhead.com/achievement=616#comments:id=6264103","https://www.wowhead.com/achievement=618#comments:id=6211471"}, "PvP")

-- Reuse researched destinations without changing another guide's step numbers.
local function copyGuideDestinations(destination, sourceID, step, selectedSteps)
    local source = guides[sourceID]
    if not source then return end
    for _, point in ipairs(source.waypoints or {}) do
        if not selectedSteps or selectedSteps[point.step] then
            destination.waypoints[#destination.waypoints + 1] = {
                mapID = point.mapID, x = point.x, y = point.y,
                step = step, label = point.label, mapName = point.mapName,
            }
        end
    end
    for _, url in ipairs(source.sources or {}) do
        destination.sources[#destination.sources + 1] = url
    end
    destination.sources[#destination.sources + 1] = source.sourceURL or source.wowheadUrl
end

