        routes = {{951}},
    },
    {
        text = "Add Honor Hold OR Thrallmar by repeatedly clearing NORMAL Shattered Halls in Hellfire Citadel, Outland. Kill the trash as well as the bosses, leave, reset outside and repeat. Its Normal kills continue beyond the caps of the lower-level Hellfire dungeons. No Flamewrought Key or old attunement is required. Count only your faction's bar.",
        points = {pin(100,47.66,51.98,12,"Normal Shattered Halls - Honor Hold / Thrallmar")},
        sources = {"https://www.wowhead.com/achievement=763#comments:id=1873687"},
    },
    {
        text = "Add Sha'tari Skyguard. Start Threat from Above with Yuula beside Shattrath's flight master and follow To Skettis to Blackwind Landing. Farm Skettis arakkoa for Shadow Dust and exchange six at a time with Severin for Elixir of Shadows; keep it active to see time-lost arakkoa. Follow the Almanac/Hazzik introduction in Flying High Over Skettis to unlock the four descendant summons and Terokk. Repeat kills, dust exchanges and those summons to Exalted; the bombing/escort dailies supplement the repeatable farm.",
        routes = {{894}},
    },
    {
        text = "Add Netherwing. Start Mordenai's Kindness in OUTLAND Shadowmoon Valley, follow the airborne Neltharaku's drake-rescue chain, free Karynaku from Zuluhed, and finish Ally of the Netherwing. Continue Blood Oath of the Netherwing and In Service of the Illidari to the disguised island camp. Finish The Great Netherwing Egg Hunt to unlock repeatable egg hand-ins, then combine eggs with the available camp/mine dailies and each rank promotion until Exalted. The Netherwing guide has the full unlock; an egg bought before those quests is not an unlocked turn-in.",
