    },
    {
        text = "For the fortieth distinct faction, add Brood of Nozdormu in the TEMPLE of Ahn'Qiraj, not the Ruins used for Cenarion Circle. Kill trash until its reputation stops at 2,999/3,000 Neutral, saving Qiraji Lord's Insignias and Ancient Qiraji Artifacts. Beyond that, use boss kills and the friendly dragons' item hand-ins near the raid entrance: Mortal Champions takes insignias, while artifacts start their own turn-in. Repeat after weekly resets. Classic Timewalking commendations are an optional badge-funded alternative while their vendor is active. This faction starts Hated, so a Neutral-to-Exalted token total is insufficient from scratch.",
        routes = {{956}},
    },
}
for _, id in ipairs({520,519,518,1014,1015}) do
    local guide = guides[id]
    for _, stage in ipairs(reputationStages) do
        local step = guide.stepCount + 1
        guide.acquisition = guide.acquisition .. "\n\n" .. step .. ". " .. stage.text
        guide.stepCount = step
        for _, route in ipairs(stage.routes or {}) do copyGuideDestinations(guide,route[1],step,route[2]) end
        for _, point in ipairs(stage.points or {}) do
            guide.waypoints[#guide.waypoints + 1] = {
                mapID = point.mapID, x = point.x, y = point.y,
                step = step, label = point.label, mapName = point.mapName,
            }
        end
        for _, url in ipairs(stage.sources or {}) do guide.sources[#guide.sources + 1] = url end
    end
    guide.tips = guide.tips .. " The complete route offers forty distinct factions for either faction, with opposing allegiances counted only once. Stop at your own milestone; already-Exalted bars need no repeat grind. Do not lower an Exalted allegiance while relying on it for this count."
end

-- Overall effort for a current max-level Retail character, including travel,
-- repetition, rare outcomes, calendar access and player coordination.
local function rate(level, reason, achievementIDs)
    for _, id in ipairs(achievementIDs) do
        local guide = guides[id]
        guide.difficulty, guide.difficultyReason = level, reason
        guide.acquisition = "Difficulty: " .. level:gsub("^%l", string.upper) .. " - " .. reason .. "\n\n" .. guide.acquisition
    end
end

